pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Lookahead: if next item fits exactly in post_residual, bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 10.0;
    }

    // Mean residual coupling: penalize bins far above mean residual (waste candidates).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New bin candidate: only attractive when it yields large usable residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced when item is large (efficient use).
        score = (bin_capacity - item_size) as f64 * 1.2 + 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear dead-space shaping.
    let mut score = pr;
    score -= norm_pr.powi(3) * 20.0;
    if norm_pr < 0.15 {
        score += (0.15 - norm_pr) * 90.0 * (1.0 - progress);
    }

    // Exact-hit closure: escalate reward for near-perfect fills.
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    }

    // Tight-fill bonus.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 20.0 * (fill - 0.75);
    }

    // Dead-residual band handling.
    if post_residual > 0 && post_residual <= 8 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 150.0;
    }

    // Lookahead: next item fits here.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fits = (post_residual - next_item_size) as f64;
            score -= fits * 0.3 * (1.0 - progress);
            if fits <= 8.0 {
                score -= 35.0 * (1.0 - fits / 8.0);
            }
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 22.0 * fit_ratio * (1.0 - progress);
            // Two-step chain: residual stays reusable after next item.
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 12 {
                score -= 3.0 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
            if gap <= 5.0 {
                score += 10.0 * (1.0 - gap / 5.0);
            }
        }
    }

    // Last-chance bin: strong preference.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

