    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;
    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 1.5 * progress) + 2.0 * x * x * (1.0 - progress);
    // Penalize near-full waste more strongly as stream progresses
    score += 1.2 * x.powi(3) * (0.5 + progress);
    // Reward tight fits (small post residual)
    score -= (1.0 - x) * (1.0 - x) * 0.8;
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.0;
    }
    // Prefer bins below mean residual (consolidate space)
    score += 0.3 * (mean_residual - pr) / cap;
    // Lookahead: favor bins where next item also fits
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 1.0;
    }
    // Mild penalty for opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into useful vs dead zones.
    // Residuals <= 20 are "dead space" (items are >= 1, but small leftovers rarely reusable);
    // residuals in [20, 50] are prime reusable pockets.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, strongly reward
    } else if pr <= 10 {
        score += 25.0; // nearly dead space, penalize
    } else if pr <= 25 {
        score += 8.0; // awkward pocket
    } else if pr <= 50 {
        score -= 12.0; // sweet spot: half-bin leftover
    } else {
        score += 3.0; // large leftover, mildly wasteful
    }

    // Modulo harmonic classes: leftovers matching common size bands (1..100 unknown, but
    // modular structure on capacity 100) predict future fit.
    let class = pr % 25;
    if class == 0 {
        score -= 6.0; // quarter-bin aligned leftover
    } else if class <= 5 {
        score += 5.0; // sliver class
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: reward proportionally to how snugly
            let snug = (pr - next_item_size) as f64;
            score -= 10.0 - snug * 0.15;
        } else {
            // next item won't fit here: penalize if we also created tight leftover
            score += 4.0;
        }
        // Harmonic pairing: item + next_item near capacity multiples suggests good packing
        let pair = item_size + next_item_size;
        if pair == bin_capacity {
            score -= 15.0;
        } else if pair > bin_capacity {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes (bin_capacity - item_size).
    // Make new bins unattractive unless the current placement would create dead space
    // and the new bin would be well-filled.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // big items justify new bins; small items should reuse open bins
        score += (1.0 - fill_frac) * 45.0;
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 15 {
            score -= 10.0; // allow escape hatch when all fits are terrible
        }
    }

    // Stream progression: late in the stream, avoid opening bins and squeeze tight.
    let progress = step_index as f64 / (total_items.max(2) as f64);
    score += progress * 4.0 * (open_bins_count as f64).sqrt();

    // Prefer filling bins below mean residual (consolidate emptier bins' contents).
    score += (mean_residual - bin_residual as f64) * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (low dead space).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after hosting next item: smaller slack is better.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack_after_next * 0.5;
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            let wasted = next_item_size - post_residual;
            score += (wasted as f64) * 1.5;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_open_fit = if next_item_size > 0 && post_residual < next_item_size { 30.0 } else { 0.0 };
        score += 90.0 + (open_bins_count as f64) * 5.0 - bad_open_fit;
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize small dead space that nothing (min size 1..100) can use later;
    // post_residual near 0 is perfect, mid-range residuals are wasteful.
    let pr = post_residual as f64;
    if pr > 0.0 {
        let waste = (pr / bin_capacity as f64).powf(1.5);
        score += 25.0 * waste * (1.0 - tightness);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: bonus if the next item fits exactly into post_residual,
    // penalty if post_residual is awkward relative to next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr && nxt >= pr - 10.0 {
            score -= 20.0; // near-perfect chain fit
        } else if nxt > pr && nxt <= bin_residual as f64 {
            score += 8.0; // next item would have fit before this placement
        }
        // Encourage leaving room proportional to lookahead size.
        score += 0.05 * (pr - nxt).abs();
    }

    // Time horizon: early in the stream, be conservative with open bins;
    // late in the stream, squeeze into existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual ->
    // favor filling existing bins over opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate (empty bin): penalize unless current residuals are low
    // or the item fits badly everywhere (large post_residual in any bin).
    if bin_residual == bin_capacity {
        let best_possible = if post_residual == bin_capacity { 0.0 } else { pr };
        let pressure = (mean_residual / bin_capacity as f64).powi(2);
        score += 45.0 - 35.0 * pressure - 0.3 * open_bins_count as f64;
        // Opening a new bin is fine if item is huge (little dead space anyway).
        if item_size >= 70 { score -= 25.0; }
        let _ = best_possible;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: normalized post-residual, shaped non-linearly.
    let mut score = x.powi(2) * (1.0 + 2.0 * progress) + x * (1.0 - progress);

    // Smooth coupling: tight fits (small post_residual) are increasingly rewarded
    // as the stream progresses (less time to recover from dead space).
    score -= (1.0 - x).powi(3) * (0.5 + 1.5 * progress);

    // Penalize leaving residual close to the smallest possible item size (dead space).
    let dead = (pr - 1.0).abs() / cap;
    score += (1.0 - dead).powi(2) * 0.8 * (0.3 + 0.7 * progress);

    // Lookahead: reward bins whose post-residual accommodates the next item smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= (1.0 - slack).powi(2) * 0.6;
        } else {
            score += ((n - pr) / cap).powi(2) * 1.2;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.05 * progress;

    // New-bin candidate: keep it attractive only when residual is full and fit is poor.
    if bin_residual == bin_capacity {
        score += 0.4 + 0.6 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: reward residuals that are "completable" ---
    // Class 0: post_residual == 0 (perfect fill) -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class 1: small dead space (1..=10) -> penalize creating unusable slivers
    if post_residual >= 1 && post_residual <= 10 {
        score += 25.0;
    }
    // Class 2: post_residual exactly divisible by common small item sizes (harmonic fit)
    // A residual divisible by 10/20/25/50 can later be perfectly filled by typical items.
    let harmonic_divisors: [u32; 6] = [10, 20, 25, 40, 50, 100];
    let mut harmonic_bonus = 0.0;
    for d in harmonic_divisors.iter() {
        if post_residual % d == 0 && post_residual > 0 {
            harmonic_bonus += 12.0;
        }
    }
    score -= harmonic_bonus;

    // --- Integer-division threshold on post_residual: bucket into capacity fractions ---
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 15.0; // nearly full: tiny leftover, mostly dead space
    } else if frac < 0.3 {
        score -= 8.0;  // comfortable zone: room for mid-size items
    } else if frac < 0.6 {
        score -= 4.0;  // large residual: still flexible
    }
    // > 0.6 residual means we barely used the bin: mild penalty vs. tight packing
    if frac > 0.6 {
        score += 5.0;
    }

    // --- Lookahead coupling: does the next item fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward, scaled by how snugly it fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 30.0 - (snug / bin_capacity as f64) * 20.0;
        } else {
            // Next item won't fit: penalize if we leave a residual that blocks nothing anyway
            score += 5.0;
        }
        // Harmonic check: post_residual is an exact multiple of next_item_size
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 20.0;
        }
    }

    // --- Last-chance bin logic: if this is the only fitting bin, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // --- Congestion control: when many bins are open, prefer tightening existing bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    let congestion = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
    score += progress * congestion * 0.5;

    // --- New-bin candidate handling: empty bin gets baseline cost ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are poor fits
        // for the current item (large post_residual elsewhere) or bins are congested.
        score = 60.0 + (open_bins_count as f64) * 0.2 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin useful for upcoming larger item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 20.0; // gaps below this are hard to fill with items >= 10... but sizes can be 1..100
    if post_residual > 0 && post_residual < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.0;
    }

    // Perfect/near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Open-bins pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // New bin baseline: prefer it only if no good existing option.
        score += 40.0 + open_bins_count as f64 * 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to use it rather than open a new bin.
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
        score -= 30.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space relative to next item
        score += 8.0;
    }

    // Mean residual coupling: prefer bins with residual close to mean (balance load)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Slight preference to fill emptier bins early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but scale by relative slack.
    let slack_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * slack_ratio * slack_ratio;

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step match: strongly reward.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: reward proportional to how well it fills remainder.
            let fill_after = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 * (1.0 - fill_after);
        } else {
            // Next item won't fit here: penalize creating dead space that blocks it.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(50.0);
        }
    }

    // Compare post_residual against mean residual: keep bin residuals balanced.
    score += 2.0 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and
    // no open bin gives a good fit. Empty bin has post_residual = capacity - item.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 >= 0.5 * bin_capacity as f64;
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64) < mean_residual * 0.35;
        if big_item && poor_fit_elsewhere {
            score -= 20.0; // opening fresh bin is fine for large items
        } else {
            score += 55.0; // discourage wasting a fresh bin
        }
    }

    // Early in stream: slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Exact fill is always best.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.05 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Dead-space penalty: post residual too small for any plausible item (min size 1).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
            // Extra reward for exact chain fit.
            if post_residual == next_item_size {
                score -= 60.0;
            }
        } else {
            // Next item won't fit here; mild penalty proportional to leftover.
            score += 0.2 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Time horizon: early in the stream, be conservative (favor compacting existing bins);
    // late in the stream, tighter fits matter more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Global state coupling: many open bins with high mean residual -> favor filling the emptiest-feeling bins.
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.1 * dev;
        // Encourage consolidation when many bins are open.
        score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin gets a moderate baseline so it only wins
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Late in the stream with many open bins, opening new bins is less attractive.
        score += 40.0 * progress;
        // But if next item is huge and won't combine with current item elsewhere, allow it.
        if next_item_size > 50 && item_size > 50 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear penalty on wasted space.
    let mut score = pr;

    // Non-linear dead-space coupling: penalize residuals that are too small
    // to be useful, smoothly via a cubic in normalized post-residual.
    let dead = (1.0 - norm_pr).powi(3) * 0.0 + norm_pr.powi(3) * 20.0;
    score -= dead;

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer tight packing (low post_residual); later, tolerate
    // spreading across bins since remaining items may fill gaps.
    let progress_coupling = pr * (0.5 + 0.5 * progress * progress);
    score += progress_coupling - 0.5 * pr;

    // Smooth interaction: post_residual vs mean residual (relative fit quality)
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 10.0 * (1.0 - progress);

    // Lookahead: reward if next item fits in post_residual (smooth bump).
    if next_item_size > 0 {
        let fits = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score -= fits * 0.3 * (1.0 - progress);
        // Smooth penalty if next item almost fits but doesn't
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * gap * 0.02;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // New-bin candidate: prefer it only when open bins are crowded and
    // post_residual of a fresh bin is large; smooth logistic gate.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        // Late in stream, opening a new bin is cheaper than wasting space.
        score -= 15.0 * progress * progress;
    }

    // Mild penalty for too many open bins, smooth in count.
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into usable bands.
    // Residuals <= 10 are dead space (min item size is ~10); heavily penalize.
    if post_residual == 0 {
        // Perfect closure of the bin: strong reward.
        score -= 200.0;
    } else if post_residual <= 10 {
        // Nearly dead residual: bad, but keep if it's the only fitting bin.
        score += 60.0;
        if fitting_bins_count == 1 {
            score -= 120.0;
        }
    } else if post_residual <= 25 {
        // Small-but-usable band: mildly penalize (fragmentation risk).
        score += 10.0;
    } else if post_residual <= 50 {
        // Mid band: neutral-ish, slight reward.
        score -= 5.0;
    } else {
        // Large residual: versatile bin, reward keeping it spacious.
        score -= 15.0;
    }

    // Harmonic class via integer division: which "slot" does post_residual fall in
    // relative to quarter-capacity? 0..=25, 26..=50, 51..=75, 76..=100.
    let quarter_class = post_residual / 26;
    score -= (quarter_class as f64) * 8.0;

    // Lookahead coupling: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: next item can land here without opening a bin.
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            // Reward tight chains (next item fills most of the remainder).
            score -= 25.0 * fit_ratio;
            if post_residual - next_item_size <= 10 {
                // Chain closes the bin almost perfectly: big reward.
                score -= 40.0;
            }
        } else {
            // Next item cannot fit here: penalize leaving a stranded gap,
            // scaled by how far off the fit is.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(40.0);
        }
    } else {
        // Last item: strongly prefer zero post_residual (perfect closure).
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the residual would be dead space, handled above).
    if fitting_bins_count == 1 && post_residual > 10 {
        score -= 50.0;
    }

    // Mean-residual coupling: if this bin is far below the mean residual, it is
    // "ragged" — prefer filling ragged bins to consolidate space.
    let dev = mean_residual - post_residual as f64;
    score -= 0.2 * dev.clamp(-50.0, 50.0);

    // Stream progression: early on, be more willing to open fresh bins for large items;
    // late in the stream, avoid new bins and squeeze into existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline score is capacity; adjust.
        // Open a new bin only if the item is large and the stream is early,
        // or no open bin gives a decent fit.
        score -= 20.0 * (1.0 - progress);
        if item_size > 60 && post_residual < 40 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            // Must open a bin: make it neutral.
            score -= 100.0;
        }
    }

    // Tight-fit bonus: item occupies most of the residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 {
        score -= 20.0 * (fill - 0.8);
    }

    // Modulo harmonic: residuals that are multiples of 10 align with typical
    // item granularities — slightly more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are nearly unusable
    // for future items (min item size is small but waste compounds).
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // worst at post_residual small-but-nonzero
    } else if post_residual > 10 && post_residual <= 25 {
        score += 12.0; // moderately awkward zone
    }

    // Reward tight fits (post_residual near zero or exactly reusable sizes)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual == item_size {
        score -= 15.0; // leaves room for an identical item
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size <= 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // dead space for the known next item
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64) * 3.0;
    } else {
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Last-chance bonus: only one bin can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual is already below the mean (compact bins).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.3;

    // Late in the stream, be greedier about closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual <= 5 {
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's post residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits with small slack: still a strong lookahead signal.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.5;
    }
    // Dead space: post residual too small for the next item (or nothing next).
    if next_item_size == 0 || post_residual < next_item_size {
        let dead = if next_item_size == 0 {
            post_residual.min(20) as f64
        } else {
            post_residual as f64
        };
        score += dead * 0.8;
    }

    // Last chance: only this bin can fit the item -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer bins tighter than the mean residual (pack dense bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Mild penalty when many bins are open: encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Slight late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0 && post_residual >= next_item_size;
        if fitting_bins_count > 0 && !good_fit_exists {
            score += 40.0;
        } else if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly favored.
    score -= (bin_capacity as f64 - post_residual as f64).sqrt() * 2.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 15.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Time horizon: early in the stream, prefer opening fresh bins to keep
    // flexibility; late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward late only if current bins are fragmented.
        score += 40.0 * (1.0 - progress);
        score -= 10.0 * progress;
        if mean_residual > 40.0 {
            score += 20.0; // plenty of space around; no need for a new bin
        }
    } else {
        // Prefer fuller bins as the stream progresses.
        score -= progress * 10.0;
        // Spread-awareness: if mean residual is high, prefer bins below mean
        // (fill the emptier ones to consolidate).
        if (bin_residual as f64) < mean_residual {
            score += 5.0;
        } else {
            score -= 5.0;
        }
    }

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * (bin_residual as f64 - post_residual as f64) * 0.05;

    // Mild reward for near-perfect packing.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress.
    // Early stream: prefer tight fills (post_residual small), dead space penalized quadratically.
    // Late stream: residual slack becomes more tolerable, so dampen the penalty.
    let tightness = pr_norm * pr_norm;                       // quadratic dead-space term
    let progress_weight = 1.0 - progress * progress;         // decays smoothly over the stream
    score += tightness * 40.0 * progress_weight;

    // Cubic interaction: penalize medium residuals early (fragmentation), less late.
    let cubic = pr_norm * pr_norm * pr_norm;
    score += cubic * 25.0 * (1.0 - progress);

    // Reward near-perfect fits (post_residual close to zero) with smooth exponential-like term.
    if pr_norm < 0.2 {
        score -= (1.0 - pr_norm / 0.2) * 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits in the resulting post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // Next item won't fit here after placement; mildly penalize wasting the fit.
        score += 4.0 * (1.0 - progress);
    }

    // New-bin candidate: keep it attractive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline neutral score; penalize opening new bins early when fragmentation is low.
        score = 55.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 25.0; // no real alternative, allow the new bin
        }
    }

    // Mild bonus for bins tighter than the mean residual (good global packing state).
    if pr < mean_residual {
        score -= 3.0 * (1.0 - pr / mean_residual.max(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 20.0;

    // Harmonic class of post_residual: dead space below 10 is nearly unusable.
    if post_residual < 10 {
        score -= 30.0;
    } else if post_residual == 0 {
        score -= 60.0;
    } else {
        // Modulo classes: residuals congruent to small mod 10 pair poorly with sizes 10..80
        let m = post_residual % 10;
        if m == 9 || m == 1 {
            score -= 5.0; // near-decade residuals still usable
        }
        // Integer-division thresholds on post_residual
        let q = post_residual / 10; // usable decade slots
        score -= q as f64 * 3.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item can chain here: strong reward, scaled by snugness
            let snug = (next_item_size as f64) / (post_residual as f64);
            score -= 15.0 + 10.0 * snug;
        } else {
            // residual too small for next item: penalize proportional waste
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * waste;
            // harmonic check: can next item's complement class still be filled later?
            if post_residual % 10 == 0 && post_residual >= 10 {
                score -= 2.0; // decade-aligned residual may catch future items
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is very full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // opening fresh bin wastes (C - item) immediately; only attractive for large items
        score = bin_capacity as f64 - 40.0 * item_frac - 10.0 * progress;
        if item_size >= 50 {
            score -= 15.0;
        }
    }

    // Slight preference for bins below mean residual (balance load) when many bins open.
    if open_bins_count > 1 {
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Lookahead: if next item fits exactly in post_residual, bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 10.0;
    }

    // Mean residual coupling: penalize bins far above mean residual (waste candidates).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New bin candidate: only attractive when it yields large usable residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced when item is large (efficient use).
        score = (bin_capacity - item_size) as f64 * 1.2 + 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fills bin
        } else if next_item_size <= post_residual {
            // next item fits; reward proportionally to how tightly it packs the remainder
            let tight = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * tight;
            // reward small leftover after the pair
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit here: penalize large post residuals that become dead space
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.3 * overflow.min(50.0);
        }
    }

    // Penalize residual far above the mean residual (hoarding space in one bin)
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: this is the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Never prefer opening a new bin over a reasonable fit unless residual is tiny
    if bin_residual == bin_capacity {
        // new-bin candidate: score = full capacity, adjusted by item size
        score = bin_capacity as f64 - item_size as f64 + 10.0;
        if next_item_size > 0 && next_item_size >= bin_residual - item_size {
            score += 5.0; // next item won't fit here either; new bin slightly safer
        }
    }

    // Small penalty for very small dead space (wasted slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 8.0;
        }
        // Exact chain fit: post_residual equals next item size exactly.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin would leave large unusable residue.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score -= 10.0 + 20.0 * progress;
        // Penalize opening a new bin when a decent fit exists elsewhere.
        if post_residual >= 10 && fitting_bins_count > 1 {
            score += 35.0;
        }
        if crowd > 3.0 {
            score -= 15.0;
        }
    } else {
        // Prefer bins that deviate favorably from the mean residual.
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.3 * dev;
    }

    // Mild preference for filling bins that are already partially used.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill;

    // Late in the stream, consolidate: discourage spreading across many bins.
    if progress > 0.7 {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress * norm_pr) - 0.5 * progress * norm_pr * norm_pr;

    let mut score = pr * (1.0 + 0.6 * progress * norm_pr) + 3.0 * poly;

    // reward near-perfect fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * progress * tightness * tightness;

    // penalize dead space that next item cannot use
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 5.0 * (ns - pr) / cap * (1.0 + progress);
        } else {
            score -= 2.0 * (pr - ns) / cap;
        }
    }

    // last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // discourage opening new bins when many bins are open with slack
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 4.0 * mean_residual / cap * (1.0 + progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo buckets on capacity fractions.
    let pr = post_residual as u32;
    let class = pr / 10; // integer-division threshold classes (0..=10)
    let phase = pr % 10; // fine phase within class

    // Dead space penalty grows super-linearly for small unusable residuals.
    if pr > 0 && pr < 10 {
        score += 60.0 - (pr as f64) * 5.0;
    }

    // Class-based reward: residuals that are perfect complement classes
    // (multiples of 10) are more likely reusable by typical item sizes.
    if phase == 0 && pr > 0 {
        score -= 12.0;
    }
    // Harmonic penalty for awkward classes: residual in 1..=9 already handled;
    // penalize classes whose residual can only host tiny items.
    match class {
        0 => score += 40.0,          // zero residual: bin sealed, fine but no future use
        1..=2 => score += 25.0,      // very small residual: near-dead space
        3..=5 => score += 8.0,       // moderate: fits mid items
        6..=8 => score -= 6.0,       // roomy: good
        _ => score -= 10.0,          // large residual: still very usable
    }

    // Lookahead coupling: reward residuals that exactly (or harmonically)
    // accommodate the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (pr as f64) >= n {
            // residual divisible-ish by next item: harmonic fit
            let rem = pr % next_item_size.max(1);
            if rem == 0 {
                score -= 15.0;
            } else {
                score -= 10.0 * (1.0 - (rem as f64) / n);
            }
        } else {
            score += 10.0; // next item can't use this residual
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer tight fills relative to mean residual state.
    score -= 0.05 * mean_residual;
    score += 0.02 * (open_bins_count as f64);

    // Progress modulation: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - (post_residual as f64) / cap);

    // New-bin candidate: make it attractive only when no open bin fits well.
