        if item_size > 65 && progress < 0.4 {
            score -= 15.0;
        }
        // No open bin can take the item: must open new bin.
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        // Late stream: prefer consolidating into existing bins.
        if progress > 0.6 {
            score += 25.0;
        }
