    score -= 0.2 * dev.clamp(-50.0, 50.0);

    // New-bin candidate: prefer it only when open bins are crowded; smooth gate.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
