        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // NEW: dead-space elasticity — mid-range residuals that can absorb the
    // next item with room to spare are more valuable than tight residuals
    // that will strand capacity; reward slack proportional to norm_pr.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 20.0 {
            score -= 0.35 * slack * (1.0 - progress) * (1.0 - norm_pr);
        }
    }

    // NEW: stranded-capacity guard — residuals just below the next item's
    // size are the worst outcome; sharpen the near-miss band with a
    // capacity-relative threshold rather than a fixed one.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        let band = (cap * 0.06).max(3.0);
        if miss <= band {
            score += 14.0 * (1.0 - miss / band);
        }
    }

    // Endgame sweep — near the stream end, residual hoarding is
    // worthless; push hard toward exact fills regardless of shape.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear dead-space shaping.
    let mut score = pr;

    // Dead-space penalty: cubic waste curve, sharpened near tiny residuals.
    let dead = norm_pr.powi(3) * 22.0;
    score -= dead;

    // Polynomial coupling of post_residual with stream progress.
    let progress_coupling = pr * (0.5 + 0.5 * progress * progress);
    score += progress_coupling - 0.5 * pr;

    // Relative fit quality vs mean residual.
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 10.0 * (1.0 - progress);

    // Lookahead: reward if next item fits in post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fits = (post_residual - next_item_size) as f64;
            score -= fits * 0.3 * (1.0 - progress);
            if fits <= 8.0 {
                score -= 35.0 * (1.0 - fits / 8.0);
            }
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 22.0 * fit_ratio * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
        }
    }

    // Tight-fill bonus.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 20.0 * (fill - 0.75);
    }

    // Dead-residual band: tiny unusable gaps are wasteful; scale with progress.
    if post_residual > 0 && post_residual <= 8 {
        score += 60.0 + 20.0 * progress;
    } else if post_residual == 0 {
        score -= 150.0;
    }

    // Last-chance bonus: favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual consolidation.
    let dev = mean_residual - pr;
    score -= 0.2 * dev.clamp(-50.0, 50.0);

    // NEW: quadratic residual-utility term — residuals that are too small to
    // host any plausible item are dead weight; residuals near half-capacity
    // are maximally reusable. Smooth U-shape centered on cap/2.
    let util_center = cap * 0.5;
    let util_dev = (pr - util_center) / cap;
    score += util_dev * util_dev * 12.0 * (1.0 - progress);

    // NEW: dead-space floor — if the post-residual cannot fit even the
    // smallest conceivable follow-up demand (approximated by a fraction of
    // the mean item footprint), treat it as lost capacity.
    if pr > 0.0 && pr < (mr * 0.35).max(6.0) {
        score += 25.0 * (1.0 - pr / (mr * 0.35).max(6.0));
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && progress < 0.4 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
