        // Exact-fill preference in a fresh bin for large items.
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        // NEW: fresh-bin waste check — opening a new bin for a small item
        // leaves a huge residual; penalize when item is far below the
        // mean demand, since existing ragged bins handle small items well.
        let small_waste = (cap - item_size as f64) / cap;
        if small_waste > 0.7 && mean_residual > 15.0 {
