        // Fragmentation guard: opening a bin for a small item when
        // mean residual is generous wastes capacity; penalize mildly.
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        // Residual-window lookahead — clean pairing in a fresh bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
