    }

    // NEW: bin-count pressure relief — when many bins are open and the
    // mean residual is low (bins nearly full), mildly discourage opening
    // fresh bins since consolidation is the dominant win.
    if bin_residual == bin_capacity && open_bins_count > 4 && mean_residual < 25.0 {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Tight fit reward: quadratic bonus for small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64) / cap * 20.0;

    // Dead-space shaping: cubic penalty plus sharp band below 15% capacity.
    score -= norm_pr.powi(3) * 20.0;
    if norm_pr < 0.15 {
        score += (0.15 - norm_pr) * 90.0 * (1.0 - progress);
    }

    // Harmonic class of post_residual.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 8 {
        score += 60.0;
    } else if post_residual < 10 {
        score -= 30.0;
    } else {
        let m = post_residual % 10;
        if m == 9 || m == 1 {
            score -= 5.0;
        }
        let q = post_residual / 10;
        score -= q as f64 * 3.0;
        if m == 0 {
            score -= 5.0; // decade-aligned residuals recombine well
        }
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let snug = (next_item_size as f64) / pr;
            score -= 15.0 + 10.0 * snug;
            let fits = (post_residual - next_item_size) as f64;
            if fits <= 8.0 {
                score -= 35.0 * (1.0 - fits / 8.0);
            }
            // Two-step chain: keep residual reusable after the next item.
            if fits > 0.0 && fits < 12.0 {
                score -= 3.0 * (1.0 - fits / 12.0) * (1.0 - progress);
            }
        } else {
            let waste = pr / cap;
            score += 8.0 * waste;
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
            if gap <= 5.0 {
                score += 10.0 * (1.0 - gap / 5.0) * (1.0 - progress);
            }
            if post_residual % 10 == 0 && post_residual >= 10 {
                score -= 2.0;
            }
        }
    }

    // Tight-fill bonus on the current fill ratio.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 20.0 * (fill - 0.75);
    }

    // Exact-hit escalation: near-perfect closures prioritized quadratically.
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Multi-fit competition: prefer bin whose post-residual matches demand.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
