    // Mean-residual consolidation: prefer filling ragged bins.
    let dev = mean_residual - pr;
    score -= 0.2 * dev.clamp(-50.0, 50.0);

    // Fragmentation guard: don't burn large residuals on tiny items.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Endgame sweep: residual hoarding worthless near stream end.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
