    let res_ratio = bin_residual as f64 / cap;
    if res_ratio <= 0.20 && fitting_bins_count > 0 {
        score -= 8.0 * (1.0 - res_ratio / 0.20) * (0.4 + 0.6 * progress);
    }

    score
}

