    // lands close to common small-item sizes (multiples of ~10), improving
    // the chance the residual is fully consumed later.
    if post_residual > 0 && post_residual <= 40 {
        let grid_dist = (post_residual as f64 - (post_residual / 10 * 10) as f64).abs();
        let grid_dist = grid_dist.min(10.0 - grid_dist);
        score += 2.5 * (grid_dist / 5.0) * (1.0 - progress);
