        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = cap - item - next_item_size as f64;
            let existing_res = (mean_residual - item).max(0.0);
            if fresh_res >= 0.0 && fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
