    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: dead space penalty.
        score += 30.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 60.0 + 12.0 * open_bins_count as f64;
    } else {
        // Slight preference for tighter bins (small residual before placement).
        score += bin_residual as f64 * 0.05;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear penalty on wasted space.
    let mut score = pr;

    // Non-linear dead-space coupling (sharpened: residuals below ~15% of
    // capacity are almost certainly dead space; punish harder there).
    let dead = norm_pr.powi(3) * 20.0;
    score -= dead;
    if norm_pr < 0.15 {
        score += (0.15 - norm_pr) * 90.0 * (1.0 - progress);
    }

    // Polynomial coupling of post_residual with stream progress.
    let progress_coupling = pr * (0.5 + 0.5 * progress * progress);
    score += progress_coupling - 0.5 * pr;

    // Smooth interaction: post_residual vs mean residual (relative fit quality).
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 10.0 * (1.0 - progress);

    // Lookahead: reward if next item fits in post_residual (smooth bump).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fits = (post_residual - next_item_size) as f64;
            score -= fits * 0.3 * (1.0 - progress);
            // Strong bonus for near-perfect chaining.
            if fits <= 8.0 {
                score -= 35.0 * (1.0 - fits / 8.0);
            }
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 22.0 * fit_ratio * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
        }
    }

    // Tight-fill bonus: strongly reward near-complete fills.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 20.0 * (fill - 0.75);
    }

    // Dead-residual band: leaving tiny unusable gaps is wasteful.
    if post_residual > 0 && post_residual <= 8 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 150.0;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual consolidation: prefer filling ragged bins.
    let dev = mean_residual - pr;
    score -= 0.2 * dev.clamp(-50.0, 50.0);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && progress < 0.4 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = cap - item_size as f64 - next_item_size as f64;
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= 0.0 && fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        // Fresh-bin gate: prefer existing bin when post-residuals are close.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64).max(0.0);
            let best_existing = (mean_residual - item_size as f64).max(0.0);
            if fresh_res <= best_existing + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
        }
        // Penalize opening a fresh bin when the item is small enough that
        // many open bins could still absorb it comfortably.
        if item_size as f64 <= cap * 0.3 && fitting_bins_count >= 2 {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Mild penalty for too many open bins, smooth in count.
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // Granularity alignment: residuals on coarse grid tend to recombine.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Residual-shape refinement: prefer mid-size residuals that can
    // plausibly host the next item; penalize awkward mid-gaps.
    if pr > 8.0 && next_item_size > 0 && next_item_size > post_residual {
        score += 4.0 * (1.0 - progress);
    }

    // Two-item lookahead window: keep bins useful in the near future.
    if next_item_size > post_residual && post_residual >= next_item_size / 2 {
        score -= 6.0 * (1.0 - progress);
    }

    // Waste-shape penalty: near-miss gaps are the main dead-space source.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score += 10.0 * (1.0 - miss / 5.0);
        }
    }

    // Multi-fit competition term — prefer the bin whose post-residual best
    // matches the remaining demand; scaled by contest intensity.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep — near the stream end, residual hoarding is worthless.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // Two-step chain lookahead — reward bins whose post-residual can host
    // both the next item and a plausible follow-up.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next < 12 {
            score -= 3.0 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
        }
    }

    // Fragmentation guard — avoid consuming a large-residual bin with a
    // tiny item when other fitting bins exist; large residuals are scarce.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Exact-hit shaping — quadratic reward for near-perfect closures,
    // smoothly extended to near-exact hits up to slack 6.
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    } else if slack > 3.0 && slack <= 6.0 {
        score -= 18.0 * (1.0 - (slack - 3.0) / 3.0);
    }

    // Mid-band residual preference — residuals in the 25-55% capacity band
    // retain recombination potential; nudge selection toward them early.
    let band = norm_pr >= 0.25 && norm_pr <= 0.55;
    if band && progress < 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Dead-space budget — price residuals that cannot host even a small
    // future item as effectively closed bins.
    if post_residual > 0 && post_residual < 20 && progress < 0.9 {
        let stranded = 20.0 - post_residual as f64;
        score += stranded * 1.5 * (1.0 - progress);
    }

    // Harmony pairing — when the next item leaves the post-residual near
    // the stream's mean residual, the bin stays reusable; reward closeness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        let closeness = 1.0 - ((after as f64 - mean_residual) / (mean_residual + 10.0)).abs().min(1.0);
        score -= 5.0 * closeness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins where the next item fits snugly after this one.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after placing both items — smaller is better.
            let two_step_slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.5 * two_step_slack;
            // Perfect two-item fill is a jackpot.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item won't fit: penalize proportionally to the leftover dead space.
            score += 10.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight fit now: reward minimal post_residual relative to mean residual.
    let mean_r = mean_residual.max(1.0);
    if (post_residual as f64) < mean_r {
        score -= 0.4 * (mean_r - post_residual as f64);
    } else {
        score += 0.2 * (post_residual as f64 - mean_r);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless the fit is terrible everywhere.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Allow opening a new bin early in the stream when open bins are scarce.
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // With lookahead: a fresh bin fits item + next item perfectly.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Late in the stream, consolidate harder (fewer wasted bins at the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

