    let mut score = post_residual as f64;

    // Core tightness reward: strongly reward filling the bin deeply.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 2.5 * fill_ratio * (bin_residual as f64);

    // Penalize post-residual dead space non-linearly: small leftovers are risky.
    let pr = post_residual as f64;
    if pr > 0.0 {
        score += (pr * pr) / bin_capacity as f64;
    }

    // Perfect / near-perfect fit bonus.
