        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the resulting residual, big reward.
    if next_item_size > 0 {
        if next_item_size as f64 <= pr {
            score -= 120.0;
            // Extra reward if the next item nearly fills the remaining space.
            let gap = pr - next_item_size as f64;
            score -= 80.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Penalize residuals that the next item cannot use (wasted space).
            score += 0.35 * (next_item_size as f64 - pr).min(next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 90.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, tighten competition: prefer tighter fits.
        score += 4.0 * (fitting_bins_count as f64 - 1.0).min(10.0) * (1.0 - fill_ratio);
    }

    // Relative residual vs. mean: prefer bins below-average residual (denser bins).
    score += 0.6 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, tolerate opening new bins less;
    // late in the stream, prefer closing out bins (fill existing ones harder).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * fill_ratio;

    // Bin-count pressure: many open bins => discourage new-bin openings implicitly
    // by rewarding placement into existing bins.
    if bin_residual != bin_capacity {
        score -= 8.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // If the item is large and would leave little waste anyway, new bin is fine.
        score -= 40.0 * fill_ratio;
