        // If no other bin fits, fitting_bins_count includes only this one; soften cost.
        if fitting_bins_count <= 1 {
            score -= 80.0;
        }
        // Late in the stream, avoid opening new bins.
        score += 60.0 * progress;
    }

    score
}

