pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear polynomial coupling of post residual with stream progress.
    // Early stream (progress ~ 0): prefer tight fits (low post residual) mildly.
    // Late stream (progress ~ 1): penalize large residuals strongly to avoid dead space.
    let base = 2.0 * x - 1.0; // in [-1, 1]
    let coupling = 1.0 + 1.5 * progress * progress; // grows quadratically with progress
    let mut score = x * coupling + 0.35 * base * base * progress;

    // Smooth reward for last-chance bins (avoid opening new bins unnecessarily).
    if fitting_bins_count == 1 {
        score -= 0.8 + 0.5 * progress;
    }

    // Smooth penalty when many bins are open: prefer consolidating into tighter fills.
    let open_norm = (open_bins_count as f64).ln() / (1.0 + (open_bins_count as f64).ln());
    score += 0.4 * open_norm * x;

    // Lookahead: smooth reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score -= (1.0 - gap).max(0.0) * 0.6 * (1.0 - progress);
    } else {
        // Last item: strongly prefer minimizing residual.
        score += 1.2 * x;
    }

    // Mild tie-break toward bins tighter than the mean residual (smooth).
    let dev = (mean_residual - pr) / cap;
    score -= 0.25 * dev.tanh();

    score
}

