    // NEW: near-miss gap shaping — small misses are the main dead-space source.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score += 10.0 * (1.0 - miss / 5.0);
        }
    }

    // Multi-fit competition: prefer bin whose post-residual matches remaining demand.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep: residual hoarding worthless near the end.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // Fragmentation guard: don't waste large residuals on tiny items.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // NEW: adaptive dead-space coupling — sharpen punishment of small
    // residuals late in the stream where closure matters most.
    if norm_pr > 0.0 && norm_pr < 0.10 && progress > 0.5 {
        score += 18.0 * (1.0 - norm_pr / 0.10) * (progress - 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose post-residual lands in a
    // "small" residue class are more likely to be filled later -> reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = post / cap;

    // Class A: post_residual divisible by 10 (aligns with typical item granularity)
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Class B: post_residual in [1..9] is dead space -> penalize strongly
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Class C: integer-division thresholds on post_residual
    let div = post_residual / 10; // 0..10 harmonic index
    score -= (div as f64) * 2.0; // larger usable remainder preferred

    // Tight fit reward: post_residual small but not dead
    if post_residual <= 5 {
        score -= 20.0; // near-perfect fit
    }

    // Modulo coupling between item_size and bin_residual (harmonic alignment)
    if bin_residual % item_size.max(1) == 0 {
        score -= 10.0; // item exactly tiles the residual
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // chain placement possible
            // harmonic match: post_residual % next_item_size == 0
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            score += 6.0; // next item won't fit here; this bin may strand
        }
    } else {
        // Last item: minimize leftover
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // more competition: prefer the best-fitting one (already via post_residual)
        score += (fitting_bins_count as f64) * 0.5;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Fresh bin: post_residual == capacity - item_size, large by construction.
        // Penalize opening a new bin unless item is big and stream is early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_frac = item_size as f64 / cap;
        let pressure = open_bins_count as f64;
        score += 30.0
            - 25.0 * size_frac
            - 10.0 * (1.0 - progress)
            + 2.0 * pressure;
        // If item nearly fills a fresh bin, opening is fine
        if size_frac > 0.8 {
            score -= 40.0;
        }
    }

    // Prefer bins below mean residual (fill emptier bins less; keep tight bins tight)
    score += (post - mean_residual) * 0.3;

    // Small global tie-breaker on residual fraction
    score += frac * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
