                score -= 3.0 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
            if gap <= 5.0 {
                score += 10.0 * (1.0 - gap / 5.0);
