    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_res = post_residual - next_item_size;
        if chain_res >= 10 && chain_res <= 40 {
            score -= 4.0 * (1.0 - progress) * (1.0 - (chain_res as f64 - 10.0) / 30.0);
        }
    }

    score
}

