    // Endgame sweep.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 55.0;
        score -= 40.0 * fill_ratio;
        if fitting_bins_count <= 1 {
            score -= 80.0;
        }
        score += 60.0 * progress;
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && progress < 0.4 {
            score -= 15.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        // Pair-fit lookahead: fresh bin can host item + next item exactly.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
            if fitting_bins_count > 0 {
                let fresh_res = cap - pair;
                let existing_res = (mean_residual - item_size as f64).max(0.0);
                if fresh_res >= 0.0 && fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                    score -= 12.0 * (1.0 - progress);
                }
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * fill_ratio * (1.0 - progress);
        }
        // Fresh-bin gate: prefer existing bins when fresh leaves similar waste.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64).max(0.0);
            let best_existing = (mean_residual - item_size as f64).max(0.0);
            if fresh_res <= best_existing + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match lookahead: reward small gaps between post_residual and next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + gap);
    }

    // Penalize dead space that can never fit typical items (small residual waste)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: bins with residuals far from mean get normalized
    score += 0.3 * ((bin_residual as f64) - mean_residual).abs();

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves a good match
    if bin_residual == bin_capacity {
        score += 15.0;
        // If lookahead would perfectly fill this new bin later, still allow it mildly
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) == 0 {
            score -= 25.0;
        }
    }

    // Late in stream: consolidation matters more, favor tight fits harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear penalty on wasted space.
    let mut score = pr;

    // Sharpened dead-space coupling.
    let dead = norm_pr.powi(3) * 20.0;
    score -= dead;
    if norm_pr < 0.15 {
        score += (0.15 - norm_pr) * 90.0 * (1.0 - progress);
    }

    // Polynomial coupling of post_residual with stream progress.
    let progress_coupling = pr * (0.5 + 0.5 * progress * progress);
    score += progress_coupling - 0.5 * pr;

    // Relative fit quality vs mean residual.
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 10.0 * (1.0 - progress);

    // Lookahead: reward if next item fits in post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fits = (post_residual - next_item_size) as f64;
            score -= fits * 0.3 * (1.0 - progress);
            if fits <= 8.0 {
                score -= 35.0 * (1.0 - fits / 8.0);
            }
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 22.0 * fit_ratio * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
        }
    }

    // Tight-fill bonus.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 20.0 * (fill - 0.75);
    }

    // Dead-residual band.
    if post_residual > 0 && post_residual <= 8 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 150.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual consolidation.
    let dev = mean_residual - pr;
    score -= 0.2 * dev.clamp(-50.0, 50.0);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && progress < 0.4 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = cap - item_size as f64 - next_item_size as f64;
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= 0.0 && fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64).max(0.0);
            let best_existing = (mean_residual - item_size as f64).max(0.0);
            if fresh_res <= best_existing + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
        }
        // NEW: refuse a fresh bin when the item would leave a large residual
        // in it while some existing bin could host it with a tight fill —
        // big items in fresh bins waste the fresh bin's full-range utility.
        if item_size as f64 <= cap * 0.45 && mean_residual >= item_size as f64 * 1.6 {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Open-bin count pressure.
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // Granularity alignment.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Mid-gap awkwardness.
    if pr > 8.0 && next_item_size > 0 && next_item_size > post_residual {
        score += 4.0 * (1.0 - progress);
    }

    // Two-item lookahead window.
    if next_item_size > post_residual && post_residual >= next_item_size / 2 {
        score -= 6.0 * (1.0 - progress);
    }

    // Waste-shape penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score += 10.0 * (1.0 - miss / 5.0);
        }
    }

    // Multi-fit competition.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // Two-step chain lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next < 12 {
            score -= 3.0 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
        }
    }

    // Fragmentation guard.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Exact-hit shaping.
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    }

    // Mid-band residual preference.
    let band = norm_pr >= 0.25 && norm_pr <= 0.55;
    if band && progress < 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // NEW: dead-space escape — when the post-residual is too small for the
    // next item but a *different* plausible size class exists, penalize
    // leaving residuals in the 9..=item_size-1 "trapped" zone more sharply;
    // this pushes selection toward bins whose leftovers stay usable.
    if pr > 8.0 && next_item_size > 0 && pr < next_item_size as f64 {
        score += (next_item_size as f64 - pr) * 0.8 * (1.0 - progress);
    }

    // NEW: residual recombination bonus — residuals that are exact multiples
    // of small item sizes are more likely to be closed out completely later.
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly (dead space)
    let pr = post_residual as f64;
    score += 0.35 * (pr / 100.0).powi(3) * 100.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Prefer fuller bins relative to mean residual
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: allow opening a new bin only when item is large
    // relative to residual (poor fit elsewhere) or many bins are open
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
        let horizon = step_index as f64 / (total_items as f64 + 1.0);
        // Early stream: favor opening bins for large items; late: consolidate
        score += 30.0 - 55.0 * tightness - 10.0 * pressure + 20.0 * horizon;
        // Don't open a new bin if an open bin fits almost perfectly
        if fitting_bins_count > 0 && (bin_residual - item_size) > (bin_residual - item_size) {
            score += 0.0;
        }
        if fitting_bins_count > 0 && post_residual >= 0 && (bin_residual - item_size) < 15 {
            score += 50.0;
        }
    }

    // Mild preference for bins that are already quite full
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
