        // NEW: open a fresh bin only if the item is large relative to the
        // mean residual — small items in a crowded stream should squeeze in.
        let squeeze = item_size as f64 / mean_residual.max(1.0);
        if squeeze < 0.45 && fitting_bins_count > 0 {
