}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: post-residual, with non-linear polynomial shaping.
    // Favor tight fits (small x) super-linearly; penalize large dead space.
    let mut score = pr * (1.0 + 2.0 * x * x) - 8.0 * (1.0 - x) * (1.0 - x);

    // Smooth progress coupling: early on, prefer filling bins loosely (keep flexibility),
    // later, aggressively minimize post_residual.
    let early = (1.0 - progress) * (1.0 - progress);
    score += 20.0 * early * x * (1.0 - x);
    score -= 25.0 * progress * progress * (1.0 - x);

    // Dead-space penalty: residual too small for typical future items.
    let dead = (1.0 - x) * (1.0 - x) * (1.0 - x);
    score += 15.0 * dead * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_quality = 1.0 - (x - nx).abs();
        if nx <= x {
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            score += 6.0 * (nx - x) * (nx - x) * cap * 0.1;
        }
    }

    // Mild penalty for spreading across many open bins vs. consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - x);

    // Slight preference toward bins below mean residual (fill emptier bins less).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear penalty on wasted space.
    let mut score = pr;

    // Non-linear dead-space coupling (sharpened: residuals below ~15% of
    // capacity are almost certainly dead space; punish harder there).
    let dead = norm_pr.powi(3) * 20.0;
    score -= dead;
    if norm_pr < 0.15 {
        score += (0.15 - norm_pr) * 90.0 * (1.0 - progress);
    }

    // Polynomial coupling of post_residual with stream progress.
    let progress_coupling = pr * (0.5 + 0.5 * progress * progress);
    score += progress_coupling - 0.5 * pr;

    // Smooth interaction: post_residual vs mean residual (relative fit quality).
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 10.0 * (1.0 - progress);

    // Lookahead: reward if next item fits in post_residual (smooth bump).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fits = (post_residual - next_item_size) as f64;
            score -= fits * 0.3 * (1.0 - progress);
            if fits <= 8.0 {
                score -= 35.0 * (1.0 - fits / 8.0);
            }
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 22.0 * fit_ratio * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
        }
    }

    // Tight-fill bonus: strongly reward near-complete fills.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 20.0 * (fill - 0.75);
    }

    // Dead-residual band: leaving tiny unusable gaps is wasteful.
    if post_residual > 0 && post_residual <= 8 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 150.0;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual consolidation: prefer filling ragged bins.
    let dev = mean_residual - pr;
    score -= 0.2 * dev.clamp(-50.0, 50.0);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && progress < 0.4 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = cap - item_size as f64 - next_item_size as f64;
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= 0.0 && fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
