            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        // Fresh-bin gate: prefer existing bin when post-residuals are comparable.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64).max(0.0);
            let best_existing = (mean_residual - item_size as f64).max(0.0);
            if fresh_res <= best_existing + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
        }
        // Penalize opening a fresh bin when the item is small and many open
        // bins could still absorb it comfortably.
        if item_size as f64 <= cap * 0.3 && fitting_bins_count >= 2 {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Mild penalty for too many open bins, smooth in count.
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // Granularity alignment: residuals on coarse grid tend to recombine.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Residual-shape refinement.
    if pr > 8.0 && next_item_size > 0 && next_item_size > post_residual {
        score += 4.0 * (1.0 - progress);
    }

    // Two-item lookahead window.
    if next_item_size > post_residual && post_residual >= next_item_size / 2 {
        score -= 6.0 * (1.0 - progress);
    }

    // Waste-shape penalty: near-miss gaps are the main dead-space source.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score += 10.0 * (1.0 - miss / 5.0);
        }
    }

