    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // Two-step chain lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next < 12 {
            score -= 3.0 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
        }
    }

    // Fragmentation guard.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Exact-hit shaping — quadratic escalation for perfect closures, now
    // smoothly extended to near-exact hits (slack 4-6).
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    } else if slack > 3.0 && slack <= 6.0 {
        score -= 18.0 * (1.0 - (slack - 3.0) / 3.0);
    }

    // Mid-band residual preference.
    let band = norm_pr >= 0.25 && norm_pr <= 0.55;
    if band && progress < 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Dead-space budget — residuals that cannot host even a small future
    // item are effectively closed bins; price them as such.
    if post_residual > 0 && post_residual < 20 && progress < 0.9 {
        let stranded = 20.0 - post_residual as f64;
        score += stranded * 1.5 * (1.0 - progress);
    }

    // Harmony pairing — post-residual near the stream's mean residual keeps
    // the bin reusable; reward proportional closeness with a smooth kernel.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        let closeness = 1.0 - ((after as f64 - mean_residual) / (mean_residual + 10.0)).abs().min(1.0);
        score -= 5.0 * closeness * (1.0 - progress);
    }

    score
}

