    let mut score = post_residual as f64;

    // Fractional fill of the bin after placement
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Harmonic classes of post_residual (modulo arithmetic):
    // post_residual divisible by 10 => "clean" slot, likely reusable by common sizes.
    let pr = post_residual as i64;
    let class = pr % 10;
    if class == 0 {
        score -= 6.0; // perfectly aligned residual, easy to fill later
    } else if class <= 3 {
        score += 5.0; // small dead sliver, nearly unusable
    } else if class >= 7 {
        score += 2.0;
    }

    // Dead-space penalty: post_residual below the minimum item size (1) is fine,
    // but below typical small sizes (<= 10) it's wasted capacity.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Reward tight fits (exact or near-exact)
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Integer-division threshold: can next item fit here?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead synergy: reward proportionally to how well it nests
            let leftover = post_residual - next_item_size;
            score -= 8.0 - (leftover as f64) * 0.15;
        } else {
            score += 3.0; // next item won't chain here
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild bias
    if bin_residual == bin_capacity {
        // Opening a new bin is good when current bins are fragmented and
        // the item would leave a bad harmonic class behind.
        let bad_fit = post_residual % 10 != 0 && post_residual < 20;
        let mut bias = 18.0;
        if bad_fit {
            bias -= 10.0;
        }
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
            bias -= 6.0; // fresh bin can host the next item too
        }
        if open_bins_count == 0 {
            bias -= 30.0;
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        bias += progress * 10.0;
        score += bias;
    }

    // Prefer bins with residual already below average (consolidate fullness)
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.05;

    // Reward high fill fraction non-linearly
    score -= fill_frac * fill_frac * 10.0;

    score
}

