        // NEW: hard anti-inflation gate — never open a fresh bin for small
        // items when any existing bin leaves a residual >= item size.
        if item_size <= 25 && fitting_bins_count > 0 && progress < 0.8 {
            score += 30.0;
        }
        // NEW: large-item fresh-bin synergy — big items justify fresh bins
        // more strongly when the fresh residual can still host next_item.
        if item_size >= 60 && next_item_size > 0 && next_item_size <= (cap - item_size as f64) {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Mild penalty for too many open bins, smooth in count.
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // Granularity alignment: residuals on coarse grid tend to recombine.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Residual-shape refinement: penalize awkward mid-gaps.
    if pr > 8.0 && next_item_size > 0 && next_item_size > post_residual {
        score += 4.0 * (1.0 - progress);
    }

    // Two-item lookahead window.
    if next_item_size > post_residual && post_residual >= next_item_size / 2 {
        score -= 6.0 * (1.0 - progress);
    }

    // Waste-shape penalty: near-miss gaps are the main dead-space source.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score += 10.0 * (1.0 - miss / 5.0);
        }
    }

    // Multi-fit competition term — prefer the bin whose post-residual best
    // matches the remaining demand.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep — near the stream end, residual hoarding is worthless.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // Two-step chain lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next < 12 {
            score -= 3.0 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
        }
    }

    // Fragmentation guard — avoid consuming a large-residual bin with a
    // tiny item when other fitting bins exist.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Exact-hit shaping — escalate reward for near-perfect closures.
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    }

    // Mid-band residual preference.
    let band = norm_pr >= 0.25 && norm_pr <= 0.55;
    if band && progress < 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // NEW: dead-space ratio term — weight residual waste by how much of the
    // stream remains, pushing harder for compaction early on.
    score += norm_pr * norm_pr * 12.0 * (1.0 - progress);

    // NEW: pair-completion shaping — reward bins whose post-residual plus the
    // next item exactly (or near-exactly) closes out the bin.
    if next_item_size > 0 && next_item_size > post_residual {
        let over = (next_item_size - post_residual) as f64;
        if over <= 2.0 {
            score += 14.0 * (1.0 - over / 2.0) * (1.0 - progress);
        }
    }

    score
}

