    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure.
        score += 20.0 + 5.0 * pressure;
    } else {
        score -= 0.5 * pressure;
    }

