    // exactly is a perfect closure; reward it strongly to eliminate dead
    // space two steps ahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after_next = post_residual - next_item_size;
        if after_next >= next_item_size as u32 {
            let tail = (after_next - next_item_size as u32) as f64;
            if tail <= 6.0 {
                score -= 14.0 * (1.0 - tail / 6.0) * (1.0 - progress);
            }
        }
    }

    // NEW: dead-space pressure — penalize residuals that no plausible item
    // (sizes 1..100) can usefully consume, weighted by stream progress.
    if pr > 0.0 && pr < 12.0 {
        // Small residuals below ~12 are mostly unusable mid-stream.
        score += (12.0 - pr) * 1.5 * (1.0 - progress);
    }

    // NEW: consolidation bias — when many bins fit, prefer the one whose
    // post-residual is smallest usable (>= next item) to keep bins tight.
    if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

