    let cap_raw = bin_capacity as f64;
    let cap = if cap_raw > 0.0 { cap_raw } else { 1.0 };
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mean = if mean_residual.is_finite() {
        mean_residual.clamp(0.0, cap)
    } else {
        0.5 * cap
    };
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    let is_new = bin_residual == bin_capacity;

    let mut score;

    if next > 0.0 && next <= post {
        let gap = post - next;
        score = post - next;
        score -= 0.20 * cap * (-gap / (0.35 * cap)).exp();

        if !is_new {
            score -= 1.10 * cap;
            score -= 0.10 * cap * (1.0 - gap / cap).max(0.0);
        }
    } else {
        score = post;

        if next > 0.0 {
            let shortfall = next - post;
            let just_missed = (1.0 - shortfall / cap).clamp(0.0, 1.0);
            score += 1.20 * post * just_missed;
        }
    }

    score += 0.08 * (post - mean);

    if is_new {
        score += (0.02 + 0.04 * progress) * cap;

        let open_supply_probability = if next > 0.0 {
            1.0 / (1.0 + ((next - mean) / (0.05 * cap)).exp())
        } else {
            1.0
        };

        score += 0.75 * cap * open_supply_probability;
        score += 0.05 * cap * (1.0 - open_supply_probability);
        score += cap * (0.005 * fitting_bins_count as f64 + 0.002 * open_bins_count as f64);
    } else {
        score -= 0.02 * cap * progress;
        score -= 0.10 * cap * (1.0 - post / cap).clamp(0.0, 1.0);

        if fitting_bins_count == 1 {
            score -= 0.08 * cap;
        }
    }

    score
}

