    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Exact-hit shaping — when the item nearly fills the bin exactly,
    // escalate the reward quadratically to prioritize perfect closures.
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    } else if slack > 3.0 && slack <= 6.0 {
        // NEW: extend the closure reward smoothly to near-exact hits.
        score -= 18.0 * (1.0 - (slack - 3.0) / 3.0);
    }

    // Mid-band residual preference — residuals in the 25-55% capacity
    // band retain the most recombination potential with typical item sizes;
    // nudge selection toward them early in the stream.
    let band = norm_pr >= 0.25 && norm_pr <= 0.55;
    if band && progress < 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // NEW: dead-space budget — residuals that cannot host even a small
    // future item are effectively closed bins; price them as such.
    if post_residual > 0 && post_residual < 20 && progress < 0.9 {
        let stranded = 20.0 - post_residual as f64;
        score += stranded * 1.5 * (1.0 - progress);
    }

    // NEW: harmony pairing — when the next item would leave the post-residual
    // near the stream's mean residual, the bin stays reusable.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        let closeness = 1.0 - ((after as f64 - mean_residual) / (mean_residual + 10.0)).abs().min(1.0);
        score -= 5.0 * closeness * (1.0 - progress);
    }

    // NEW: combined residual-fit lookahead — when the current item plus the
    // next item nearly exhausts this bin, reward the tight two-item closure
    // more strongly than either term alone, reducing stranded slivers.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_slack = post_residual - item_size.min(bin_residual) as u32;
        let _ = pair_slack;
        let two_slack = bin_residual as i64 - item_size as i64 - next_item_size as i64;
        if two_slack >= 0 && two_slack <= 4 {
            score -= 20.0 * (1.0 - two_slack as f64 / 4.0) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a super-linear penalty on slack.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * tightness * tightness;

    // Reward near-exact fills.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Penalize dead space too small for typical items (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let combo_waste = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.25 * combo_waste;
        } else {
            // Next item won't chain here; mild penalty scaled by overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.08 * overshoot;
        }
    } else {
        // Last item: prefer to dump into any existing bin rather than open one.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer bins that are more "used up" (smaller residual).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Prefer bins with residual below the mean (denser bins first).
    score += 0.10 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in the stream, be more willing to open new bins
    // (score new-bin candidates higher); late in stream, avoid new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and as more bins are open.
        score += 20.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
        // But if current bin fit is terrible (large post_residual), new bin looks better.
        score -= 0.10 * post_residual as f64;
    } else {
        // Existing bin: reward more when stream is late.
        score -= 10.0 * progress;
    }

    // Mild penalty for opening bins when many are already open and mean residual is high.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear dead-space shaping.
    let mut score = pr;
    score -= norm_pr.powi(3) * 20.0;
    if norm_pr < 0.15 {
        score += (0.15 - norm_pr) * 90.0 * (1.0 - progress);
    }

    // Exact-hit closure: escalate reward for near-perfect fills.
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    }

    // Tight-fill bonus.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 20.0 * (fill - 0.75);
    }

    // Dead-residual band handling.
    if post_residual > 0 && post_residual <= 8 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 150.0;
    }

    // Lookahead: next item fits here.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fits = (post_residual - next_item_size) as f64;
            score -= fits * 0.3 * (1.0 - progress);
            if fits <= 8.0 {
                score -= 35.0 * (1.0 - fits / 8.0);
            }
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 22.0 * fit_ratio * (1.0 - progress);
            // Two-step chain: residual stays reusable after next item.
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 12 {
                score -= 3.0 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
            if gap <= 5.0 {
                score += 10.0 * (1.0 - gap / 5.0);
            }
        }
    }

    // Last-chance bin: strong preference.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual consolidation.
    let dev = mean_residual - pr;
    score -= 0.2 * dev.clamp(-50.0, 50.0);

    // Relative fit quality against mean residual.
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 10.0 * (1.0 - progress);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && progress < 0.4 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = cap - item_size as f64 - next_item_size as f64;
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= 0.0 && fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        // Fresh-bin gate: prefer existing bin when residuals are comparable.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64).max(0.0);
            let best_existing = (mean_residual - item_size as f64).max(0.0);
            if fresh_res <= best_existing + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
        }
        // NEW: waste accounting for fresh-bin decision — a fresh bin is only
        // justified if the item's leftover from a fresh bin is meaningfully
        // smaller than what the best existing bin would leave behind.
        if fitting_bins_count > 0 {
            let fresh_left = (cap - item_size as f64).max(0.0);
            let best_existing_left = (mean_residual - item_size as f64).max(0.0);
            if fresh_left > best_existing_left + 12.0 {
                score += 30.0 * (1.0 - progress);
            }
        }
    }

    // Mild open-bin count penalty.
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // Granularity alignment.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Mid-band residual preference early in stream.
    if norm_pr >= 0.25 && norm_pr <= 0.55 && progress < 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Two-item lookahead window.
    if next_item_size > post_residual && post_residual >= next_item_size / 2 {
        score -= 6.0 * (1.0 - progress);
    }

    // Residual-shape refinement — penalize awkward mid-gaps that
    // cannot host the next item, encouraging consolidation elsewhere.
    if pr > 8.0 && next_item_size > 0 && next_item_size > post_residual {
        score += 4.0 * (1.0 - progress);
    }

    // Near-miss gap shaping — small misses are the main dead-space source.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score += 10.0 * (1.0 - miss / 5.0);
        }
    }

    // Multi-fit competition: prefer bin whose post-residual matches remaining demand.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep: residual hoarding worthless near the end.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // Fragmentation guard: don't waste large residuals on tiny items.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Adaptive dead-space coupling — sharpen punishment of small
    // residuals late in the stream where closure matters most.
    if norm_pr > 0.0 && norm_pr < 0.10 && progress > 0.5 {
        score += 18.0 * (1.0 - norm_pr / 0.10) * (progress - 0.5);
    }

    // NEW: harmonic pairing — reward bins whose post-residual exactly
    // complements the next item plus a small follow-up, anticipating a
    // full closure two steps ahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && next_item_size as f64 <= after_next as f64 + 2.0 {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // NEW: late-stream exact-fit escalation — near the end, prioritize
    // bins that close perfectly, since residual reuse is no longer viable.
    if progress > 0.7 && slack == 0.0 {
        score -= 25.0 * (progress - 0.7) / 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post-residual, softly normalized.
    let mut score = pr / cap;

    // Smooth quadratic coupling: dead space in the "awkward" mid-range is worst.
    let x = pr / cap;
    let awkward = 4.0 * x * (1.0 - x); // peaks at half-full residual
    score += 0.35 * awkward * awkward;

    // Perfect fit reward, scaled by stream progress (tight packing matters more later).
    if post_residual == 0 {
        score -= 1.5 + 1.0 * progress;
    }

    // Lookahead: penalize leaving residual that exactly fails to fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        // smooth proximity term: how close pr is to nxt (from either side)
        let gap = (pr as f64 - nxt).abs() / cap;
        score += 0.8 * (1.0 - fits_next) * (1.0 - gap) * (1.0 - gap);
        score -= 0.4 * fits_next * (1.0 - gap) * (1.0 - gap);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with residual below mean (consolidating emptier space elsewhere).
    score += 0.15 * (mean_residual - pr) / cap;

    // Mild new-bin penalty that decays with progress (avoid bin proliferation early).
    if bin_residual == bin_capacity {
        score += 0.6 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
