    // capacity are almost certainly dead space; punish harder there).
    let dead = norm_pr.powi(3) * 20.0;
    score -= dead;
    if norm_pr < 0.15 {
        score += (0.15 - norm_pr) * 95.0 * (1.0 - progress);
    }

    // Polynomial coupling of post_residual with stream progress.
    let progress_coupling = pr * (0.5 + 0.5 * progress * progress);
    score += progress_coupling - 0.5 * pr;

    // Smooth interaction: post_residual vs mean residual (relative fit quality).
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 10.0 * (1.0 - progress);

    // Lookahead: reward if next item fits in post_residual (smooth bump).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fits = (post_residual - next_item_size) as f64;
            score -= fits * 0.3 * (1.0 - progress);
            // Strong bonus for near-perfect chaining.
            if fits <= 8.0 {
                score -= 38.0 * (1.0 - fits / 8.0);
            }
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 22.0 * fit_ratio * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
        }
    }

    // Tight-fill bonus: strongly reward near-complete fills.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 20.0 * (fill - 0.75);
    }

    // Dead-residual band: leaving tiny unusable gaps is wasteful.
    if post_residual > 0 && post_residual <= 8 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 150.0;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual consolidation: prefer filling ragged bins.
    let dev = mean_residual - pr;
    score -= 0.2 * dev.clamp(-50.0, 50.0);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && progress < 0.4 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = cap - item_size as f64 - next_item_size as f64;
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= 0.0 && fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        // Fresh-bin gate: prefer existing bins unless a fresh bin would
        // leave a substantially better residual for the next item.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64).max(0.0);
            let best_existing = (mean_residual - item_size as f64).max(0.0);
            if fresh_res <= best_existing + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
            // NEW: only open a fresh bin if it can chain the next item
            // better than any existing bin could after this placement.
            let fresh_after = fresh_res.saturating_sub(next_item_size as f64);
            let existing_after = (best_existing - next_item_size as f64).max(0.0);
            if fresh_res >= next_item_size as f64 && existing_after > fresh_after + 15.0 {
                score -= 20.0 * (1.0 - progress);
            }
        }
    }

    // Mild penalty for too many open bins, smooth in count.
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // Granularity alignment: residuals on coarse grid tend to recombine.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Residual-shape refinement: prefer mid-size residuals that can
    // plausibly host the next item; penalize awkward mid-gaps.
    if pr > 8.0 && next_item_size > 0 && next_item_size > post_residual {
        score += 4.0 * (1.0 - progress);
    }

    // Two-item lookahead window: keep bins useful in the near future.
    if next_item_size > post_residual && post_residual >= next_item_size / 2 {
        score -= 6.0 * (1.0 - progress);
    }

    // Waste-shape penalty: near-miss gaps are the main dead-space source.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 5.0 {
            score += 10.0 * (1.0 - miss / 5.0);
        }
    }

    // Multi-fit competition term — prefer the bin whose post-residual best
    // matches the remaining demand; scaled by contest intensity.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep — near the stream end, residual hoarding is worthless.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // Two-step chain lookahead — reward bins whose post-residual can host
    // both the next item and a plausible follow-up, keeping the residual
    // reusable rather than letting it become dead space.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next < 12 {
            score -= 3.0 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
        }
    }

    // Fragmentation guard — avoid consuming a large-residual bin with a
    // tiny item when other fitting bins exist; large residuals are scarce.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Exact-hit shaping — when the item nearly fills the bin exactly,
    // escalate the reward quadratically to prioritize perfect closures.
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    }
    // NEW: extend the exact-hit shaping to a wider near-closure band with
    // a milder slope, catching 4-10 unit slacks that would otherwise be
    // stranded as dead space.
    else if slack > 3.0 && slack <= 10.0 {
        score -= 12.0 * (1.0 - (slack - 3.0) / 7.0);
    }

    // Mid-band residual preference — residuals in the 25-55% capacity
    // band retain the most recombination potential with typical item sizes.
    let band = norm_pr >= 0.25 && norm_pr <= 0.55;
    if band && progress < 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // NEW: residual divisibility synergy — residuals that are multiples of
    // small common item sizes (2, 5) are more likely to be exactly filled
    // by a future item; reward them mildly, especially early on.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.0 * (1.0 - progress);
    }

    // NEW: overshoot guard — placing an item that leaves a residual just
    // below the next item's size wastes the difference; penalize
    // proportionally to how close the miss is, scaled by remaining stream.
    if next_item_size > post_residual && post_residual > 0 && progress < 0.9 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 12.0 {
            score += 1.5 * miss * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-residual (mod-10 classes) ----
    // Residuals divisible by 10 are "harmonic": they are more likely to be
    // perfectly reused by later items (sizes 10..80 in a 100-capacity world).
    let pr = post_residual;
    let harmonic = (pr % 10 == 0) as f64;
    score -= 6.0 * harmonic;

    // Penalize small dead zones (1..=9) harder the smaller they are:
    // they are nearly unusable. Nonlinear penalty peaking at very small pr.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.5;
    }

    // ---- Perfect fit: huge reward ----
    if pr == 0 {
        score -= 40.0;
    }

    // ---- Tight fit reward: item fills bin to a harmonic fraction ----
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.75 {
        score -= 8.0 * (fill - 0.75);
    }

    // ---- Lookahead coupling: does post_residual admit next_item_size? ----
    if next_item_size > 0 {
        if pr >= next_item_size {
            // This placement keeps a slot for the next item: reward, more so
            // if the leftover after the next item is again harmonic.
            let pr2 = pr - next_item_size;
            let mut bonus = 4.0;
            if pr2 % 10 == 0 { bonus += 4.0; }
            if pr2 == 0 { bonus += 8.0; }
            score -= bonus;
        } else if pr > 0 && pr < next_item_size {
            // Leaves a gap smaller than the next item: penalize proportionally
            // to how "wasted" the space is relative to next item.
            score += (next_item_size - pr) as f64 * 0.35;
        }
    }

    // ---- Last-chance bin: strongly favor using it before opening a new one ----
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // ---- New-bin candidate logic: keep it competitive only when open bins
    //      are fragmented or this is a large item early in the stream ----
    if bin_residual == bin_capacity {
        // Base handicap so new bins are chosen only for good reason.
        let mut new_bin = 18.0;
        // More open bins with high mean residual => fragmentation => new bin ok.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 2 && mean_residual > 25.0 {
            new_bin -= 10.0;
        }
        // Large items early: better to start fresh than cram.
        if item_size > 60 && progress < 0.5 {
            new_bin -= 6.0;
        }
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 70 {
            new_bin -= 4.0;
        }
        score += new_bin;
    }

    // ---- Mild stream-phase shaping: late in the stream, consolidate hard ----
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
