    // Base: prefer tight fits (small post_residual), but not so tight it's dead space.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            // Perfect chaining: next item fills this bin completely.
            score -= 60.0;
        } else if post >= nxt {
            // Next item fits here too: gap shrinks toward a perfect fit.
            let gap = post - nxt;
            score -= (30.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
