            // penalize proportionally to how small (unusable) it is.
            let unusable = post / 100.0;
            score += 25.0 * (1.0 - unusable).min(1.0);
            // Extra penalty if the leftover is smaller than the minimum plausible item.
            if post < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item: simply minimize leftover.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
