    // after placing it can still absorb the next item, this bin sustains a
    // chain; reward proportional to how much slack survives the chain.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let chain_slack = post_residual - next_item_size;
        let usable = chain_slack.min(item_size.max(1));
