            if gap <= 5.0 {
                score += 10.0 * (1.0 - gap / 5.0) * (1.0 - progress);
            }
        }
    } else {
        score -= 35.0 * (1.0 - norm_pr);
    }

    // Tight-fill bonuses with exact-hit escalation.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 22.0 * (fill - 0.75);
    }
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    }

    // Dead-residual band / perfect fill.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 8 {
        score += 60.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // Last-chance preference.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual consolidation.
    let dev = mean_residual - pr;
    score -= 0.22 * dev.clamp(-50.0, 50.0);

    // Open-bin pressure, smooth.
    score += open_bins_count as f64 * (1.2 + 1.8 * progress);
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // Granularity alignment.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Mid-band residual preference early in the stream.
    if norm_pr >= 0.25 && norm_pr <= 0.55 && progress < 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation guard.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Multi-fit competition term.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // Waste-aware residual bucket penalty.
    if post_residual > 0 && progress < 0.9 {
        let dead_zone = if post_residual < 24 { (post_residual as f64).min(24.0) / 24.0 } else { 0.0 };
        score += 9.0 * dead_zone * (1.0 - progress);
        if post_residual >= 25 && post_residual <= 60 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Tightness-of-fit variance reduction.
    if post_residual > 0 && mean_residual > 0.0 {
        let spread = ((pr - mean_residual) / mean_residual).abs();
        score += 4.0 * spread.min(2.0) * progress;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && item_size as f64 > 0.85 * cap && progress < 0.4 {
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64 - next_item_size as f64).max(0.0);
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress);
            }
            let fresh_full = (cap - item_size as f64).max(0.0);
            if fresh_full <= existing_res + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
            if fresh_res <= 10.0 && existing_res > 20.0 {
                score -= 20.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        if item_size == bin_capacity {
            score -= 120.0;
        }
        // Fresh-bin gate: open a fresh bin only when its post-fit residual
        // clearly dominates what any existing bin could leave.
        let fresh_after = (cap - item_size as f64).max(0.0);
        let best_existing_after = (mean_residual - item_size as f64).max(0.0);
        if fresh_after > best_existing_after + 8.0 {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
        // Guard against opening bins for small items late.
        if item_size < 40 && progress > 0.45 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        // Two-item lookahead gate: pair fits almost perfectly in a fresh bin.
        if next_item_size > 0 {
            let pair_res = cap - item_size as f64 - next_item_size as f64;
            if pair_res >= 0.0 && pair_res <= 8.0 && progress < 0.85 {
                score -= 26.0 * (1.0 - pair_res / 8.0) * (1.0 - progress);
            }
        }
        // Snug-fit fresh-bin bonus.
        if fitting_bins_count > 0 && item_size as f64 > 0.7 * cap {
            let snug = (cap - item_size as f64) <= 20.0;
            let stranded = mean_residual > item_size as f64 + 25.0;
            if snug && stranded {
                score -= 16.0 * (1.0 - progress);
            }
        }
        // NEW: open a fresh bin when no existing bin can even hold the item's
        // next companion — avoid stranding the next item entirely.
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size as f64 > mean_residual.max(0.0) {
            let fresh_pair_res = (cap - item_size as f64 - next_item_size as f64).max(0.0);
            if fresh_pair_res < 15.0 {
                score -= 22.0 * (1.0 - progress);
            }
        }
    }

    // Residual-hoarding penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size + 40 && progress < 0.8 {
        score += 6.0 * (1.0 - progress);
    }

    // Pair-completion bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0 * (1.0 - progress);
    }

    // Near-miss chain sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 4.0 {
            score += 14.0 * (1.0 - miss / 4.0) * (1.0 - progress);
        }
    }

    // Adaptive consolidation — late stream, close bins out aggressively.
    if progress > 0.7 && post_residual > 0 {
        score += pr * 0.25 * (progress - 0.7) / 0.3;
    }

    // Two-item chain packing.
    if post_residual > 0 && next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0 * (1.0 - norm_pr) * (1.0 - progress);
    }

    // Residual symmetry: multiples of 5 are likelier future item sizes.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.0 * (1.0 - progress);
    }

    // Large-item reservation.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress);
    }

    // Dead-space elimination sweep.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // Mid-residual band tightening.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // Near-exact fill escalation.
    if post_residual > 0 && post_residual <= 4 {
        score -= (5.0 - post_residual as f64) * 10.0 * (1.0 + 0.5 * (1.0 - progress));
    }

    // NEW: combined fine-grained fit + lookahead compaction. Reward bins
    // where this item AND the next both nest tightly (combined slack small),
    // scaled by how scarce fitting alternatives are.
    if next_item_size > 0 && post_residual > 0 {
        let chain_slack = post_residual as f64 - item_size.min(post_residual) as f64;
        let pair_slack = (post_residual as i64 - item_size as i64 - next_item_size as i64).abs();
        if pair_slack <= 10 && next_item_size <= post_residual {
            let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
            score -= (12.0 + 8.0 * scarcity) * (1.0 - pair_slack as f64 / 10.0) * (1.0 - progress);
        }
        // Penalize leaving a residual that neither the next item nor common
        // small sizes (1..=10) can refill, mid-stream.
        if post_residual > 10 && next_item_size > post_residual && progress < 0.75 {
            score += 5.0 * (1.0 - progress) * (post_residual as f64 / cap);
        }
    }

    // NEW: prefer bins whose post-residual matches the distribution's
    // typical leftover demand (mean_residual), tightening consolidation.
    if post_residual > 0 && mean_residual > 1.0 {
        let align = 1.0 - ((pr - mean_residual) / mean_residual.max(15.0)).abs().min(1.0);
        score -= 6.0 * align * align * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Sharpened quartic dead-space penalty (tightened coefficients).
    let dead = norm_pr.powi(3) * 27.0 + norm_pr.powi(4) * 21.0;
    score -= dead;
    if norm_pr < 0.13 && post_residual > 0 {
        score += (0.13 - norm_pr) * 105.0 * (1.0 - progress);
    }

    // Polynomial progress coupling.
    score += pr * (0.5 * progress * progress);

    // Relative fit quality vs mean residual.
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 11.0 * (1.0 - progress);

    // Lookahead chaining with two-step window.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fits = (post_residual - next_item_size) as f64;
            score -= fits * 0.32 * (1.0 - progress);
            if fits <= 8.0 {
                score -= 38.0 * (1.0 - fits / 8.0);
            }
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 26.0 * fit_ratio * (1.0 - progress);
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 12 {
                score -= 4.0 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
            }
            if after_next >= item_size {
                score -= 11.0;
            }
            if after_next >= next_item_size {
                score -= 7.0 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.022;
            if gap <= 5.0 {
                score += 11.0 * (1.0 - gap / 5.0) * (1.0 - progress);
            }
        }
    } else {
        score -= 38.0 * (1.0 - norm_pr);
    }

    // Tight-fill bonuses with exact-hit escalation.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 38.0 * (fill - 0.9) + 16.0;
    } else if fill > 0.75 {
        score -= 24.0 * (fill - 0.75);
    }
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 48.0 * (1.0 - slack / 3.0);
    }

    // Dead-residual band / perfect fill.
    if post_residual == 0 {
        score -= 160.0;
    } else if post_residual <= 8 {
        score += 62.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score -= 62.0;
        }
    }

    // Last-chance preference.
    if fitting_bins_count == 1 {
        score -= 48.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual consolidation.
    let dev = mean_residual - pr;
    score -= 0.24 * dev.clamp(-50.0, 50.0);

    // Open-bin pressure, smooth.
    score += open_bins_count as f64 * (1.25 + 1.9 * progress);
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // Granularity alignment.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Mid-band residual preference early in the stream.
    if norm_pr >= 0.25 && norm_pr <= 0.55 && progress < 0.5 {
        score -= 6.5 * (1.0 - progress);
    }

    // Fragmentation guard.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Multi-fit competition term.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 9.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep.
    if progress > 0.85 {
        score += pr * 0.16;
        if post_residual == 0 {
            score -= 65.0 * (progress - 0.85) / 0.15;
        }
    }

    // Waste-aware residual bucket penalty.
    if post_residual > 0 && progress < 0.9 {
        let dead_zone = if post_residual < 22 { (post_residual as f64).min(22.0) / 22.0 } else { 0.0 };
        score += 10.0 * dead_zone * (1.0 - progress);
        if post_residual >= 25 && post_residual <= 60 {
            score -= 5.5 * (1.0 - progress);
        }
    }

    // Tightness-of-fit variance reduction.
    if post_residual > 0 && mean_residual > 0.0 {
        let spread = ((pr - mean_residual) / mean_residual).abs();
        score += 4.0 * spread.min(2.0) * progress;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 27.0 * crowding * (0.5 + progress);
        score -= 16.0 * progress * progress;
        if item_size > 65 && item_size as f64 > 0.85 * cap && progress < 0.4 {
            score -= 19.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 26.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 19.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 32.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64 - next_item_size as f64).max(0.0);
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 13.0 * (1.0 - progress);
            }
            let fresh_full = (cap - item_size as f64).max(0.0);
            if fresh_full <= existing_res + 10.0 {
                score += 15.0 * (1.0 - progress);
            }
            if fresh_res <= 10.0 && existing_res > 20.0 {
                score -= 22.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 11.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        if item_size == bin_capacity {
            score -= 120.0;
        }
        // Fresh-bin gate: open a fresh bin only when its post-fit residual
        // clearly dominates what any existing bin could leave.
        let fresh_after = (cap - item_size as f64).max(0.0);
        let best_existing_after = (mean_residual - item_size as f64).max(0.0);
        if fresh_after > best_existing_after + 8.0 {
            score -= 15.0 * (1.0 - progress);
        } else {
            score += 11.0 * (1.0 - progress);
        }
        // Guard against opening bins for small items late.
        if item_size < 40 && progress > 0.45 && fitting_bins_count > 0 {
            score += 23.0 * progress;
        }
        // Prefer a fresh bin for large snug items when existing bins strand space.
        if fitting_bins_count > 0 && item_size as f64 > 0.7 * cap {
            let snug = (cap - item_size as f64) <= 20.0;
            let stranded = mean_residual > item_size as f64 + 25.0;
            if snug && stranded {
                score -= 17.0 * (1.0 - progress);
            }
        }
        // NEW: pair-completion in a fresh bin — if item + next item nearly
        // fills a fresh bin, opening it now is near-optimal.
        if next_item_size > 0 {
            let pair_after = (cap - item_size as f64 - next_item_size as f64).max(0.0);
            if pair_after <= 8.0 {
                score -= 20.0 * (1.0 - pair_after / 8.0) * (1.0 - progress);
            }
        }
    }

    // Residual-hoarding penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size + 40 && progress < 0.8 {
        score += 6.5 * (1.0 - progress);
    }

    // Pair-completion bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 22.0 * (1.0 - progress);
    }

    // Near-miss chain sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 4.0 {
            score += 15.0 * (1.0 - miss / 4.0) * (1.0 - progress);
        }
    }

    // Adaptive consolidation — late stream, close bins out aggressively.
    if progress > 0.7 && post_residual > 0 {
        score += pr * 0.27 * (progress - 0.7) / 0.3;
    }

    // Two-item chain packing: next item exactly filling the post-residual.
    if post_residual > 0 && next_item_size > 0 && next_item_size == post_residual {
        score -= 13.0 * (1.0 - norm_pr) * (1.0 - progress);
    }

    // Residual symmetry: multiples of 5 are likelier future item sizes.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.5 * (1.0 - progress);
    }

    // Large-item reservation: keep residual space for looming big items.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.5 * (1.0 - progress);
    }

    // Dead-space elimination sweep.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 17.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // Mid-residual band tightening (30-50 dead zone).
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 8.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 20.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // NEW: three-way residual triage — residuals in the 13-24 band are the
    // hardest to refill; penalize them extra mid-stream unless the next item
    // can consume them.
    if post_residual >= 13 && post_residual <= 24 && progress < 0.7 {
        let refillable = next_item_size > 0 && next_item_size <= post_residual;
        if !refillable {
            score += 5.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 18.0).abs() / 6.0).max(0.0));
        }
    }

    // NEW: consolidation incentive — when many bins are open and this pick
    // leaves a residual close to the mean, encourage merging behavior.
    if open_bins_count > 4 && post_residual > 0 {
        let closeness = 1.0 - ((pr - mean_residual) / (mean_residual + 10.0)).abs().min(1.0);
        score -= 3.0 * closeness * (open_bins_count as f64 / 20.0).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
