    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && item_size as f64 > 0.85 * cap && progress < 0.4 {
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64 - next_item_size as f64).max(0.0);
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress);
            }
            let fresh_full = (cap - item_size as f64).max(0.0);
            if fresh_full <= existing_res + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
            if fresh_res <= 10.0 && existing_res > 20.0 {
                score -= 20.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        if item_size == bin_capacity {
            score -= 120.0;
        }
        // Fresh-bin gate: open a fresh bin only when its post-fit residual
        // clearly dominates what any existing bin could leave.
        let fresh_after = (cap - item_size as f64).max(0.0);
        let best_existing_after = (mean_residual - item_size as f64).max(0.0);
        if fresh_after > best_existing_after + 8.0 {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
        // Guard against opening bins for small items late.
        if item_size < 40 && progress > 0.45 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        // Two-item lookahead gate: pair fits almost perfectly in a fresh bin.
        if next_item_size > 0 {
            let pair_res = cap - item_size as f64 - next_item_size as f64;
            if pair_res >= 0.0 && pair_res <= 8.0 && progress < 0.85 {
                score -= 26.0 * (1.0 - pair_res / 8.0) * (1.0 - progress);
            }
        }
        // Snug-fit fresh-bin bonus.
        if fitting_bins_count > 0 && item_size as f64 > 0.7 * cap {
            let snug = (cap - item_size as f64) <= 20.0;
            let stranded = mean_residual > item_size as f64 + 25.0;
            if snug && stranded {
                score -= 16.0 * (1.0 - progress);
            }
        }
    }

    // Residual-hoarding penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size + 40 && progress < 0.8 {
        score += 6.0 * (1.0 - progress);
    }

    // Pair-completion bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0 * (1.0 - progress);
    }

    // Near-miss chain sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 4.0 {
            score += 14.0 * (1.0 - miss / 4.0) * (1.0 - progress);
        }
    }

    // Adaptive consolidation — late stream, close bins out aggressively.
    if progress > 0.7 && post_residual > 0 {
        score += pr * 0.25 * (progress - 0.7) / 0.3;
    }

    // Two-item chain packing: next item exactly filling the post-residual.
    if post_residual > 0 && next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0 * (1.0 - norm_pr) * (1.0 - progress);
    }

    // Residual symmetry: multiples of 5 are likelier future item sizes.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.0 * (1.0 - progress);
    }

    // Large-item reservation: keep residual space for looming big items.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress);
    }

    // Dead-space elimination sweep.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // Mid-residual band tightening — penalize 30-50 dead zone mid-stream.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead: next item lands residual within 2 units of zero.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // Near-exact fill escalation — tiny sliver residuals, scaled by alternatives.
    if post_residual > 0 && post_residual <= 4 {
        score -= (5.0 - post_residual as f64) * 10.0 * (1.0 + 0.5 * (1.0 - progress));
    }

    // Sliver-residual competition — prefer smallest leftover relative to next item.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 {
        let next_f = next_item_size as f64;
        if pr >= next_f {
            let chain_eff = next_f / pr;
            score -= 6.0 * chain_eff * (1.0 - progress);
        }
    }

    // Residual-target alignment — reward leftovers matching typical leftover scale.
    if post_residual > 0 && mr > 1.0 {
        let band = ((pr - mr) / mr).abs();
        if band < 0.15 {
            score -= 5.0 * (1.0 - band / 0.15) * (1.0 - progress);
        }
    }

    // NEW: dual-lookahead compaction — combine fine-grained residual fitting
    // with next-item anticipation: reward bins where the next item fits AND
    // the remaining after-next residual is itself reusable (>= 25% of cap
    // or <= 10 units), coupling chain quality with residual granularity.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let after_next = (post_residual - next_item_size) as f64;
        let reusable = after_next >= 0.25 * cap || (after_next > 0.0 && after_next <= 10.0);
        if reusable {
            let tight = 1.0 - (after_next / cap).min(1.0);
            score -= 9.0 * (0.4 + 0.6 * tight) * (1.0 - progress);
        }
    }

    // NEW: waste-floor sharpening — bins whose post-residual falls into the
    // unrecoverable band (next item cannot use it, and it's too small to be
    // worth hoarding) get a progressive quadratic penalty weighted by how
    // many alternative bins exist.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && post_residual < 20 && fitting_bins_count > 1 {
        let waste = (20.0 - pr) / 20.0;
        score += 11.0 * waste * waste * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // NEW: fresh-bin exact-pair dominance — open a new bin only if the pair
    // (item, next) closes it better than the best existing bin could close
    // after taking the item; this sharpens the fresh-bin gate with lookahead.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let pair_res = (cap - item_size as f64 - next_item_size as f64).max(0.0);
        let best_existing_pair = (mean_residual - item_size as f64 - next_item_size as f64).max(0.0);
        if pair_res <= 5.0 && best_existing_pair > 15.0 {
            score -= 20.0 * (1.0 - progress);
        } else if pair_res > best_existing_pair + 12.0 {
            score += 16.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
