        }
    }

    // NEW: residual-match scoring — prefer the bin whose post-residual
    // best matches the mean residual of the population (harmonic packing),
    // weighted more heavily mid-stream where choices matter most.
    if post_residual > 0 && mean_residual > 1.0 {
        let match_err = ((pr - mean_residual) / mean_residual).abs();
        score -= 6.0 * (1.0 - match_err.min(1.0)) * (1.0 - progress) * (1.0 - progress);
    }

    // NEW: triple-chain lookahead — if next item fits and the residual
    // after that still exceeds the item size by a wide margin, this bin
    // can absorb a third item; reward proportional to remaining slack.
    if next_item_size > 0 && post_residual > next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 >= item_size {
            score -= 5.0 * (1.0 - progress) * (r2.min(40) as f64 / 40.0);
        }
    }

    score
}

