pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual
    let item_n = item_size as f64 / cap;
    let next_n = next_item_size as f64 / cap;

    // Base: prefer small post residual, with non-linear shaping
    let mut score = r * (1.0 + 0.5 * rn * rn);

    // Smooth polynomial coupling with stream progress: later in stream,
    // increasingly penalize leftover dead space (quartic growth)
    let progress_penalty = rn * rn * (0.25 + 3.0 * t * t * t) * 40.0;
    score += progress_penalty;

    // Interaction: item size vs residual — reward tight fits smoothly
    let tightness = (item_n - rn).abs();
    score += 20.0 * tightness * (1.0 - rn) * (1.0 + t);

    // Lookahead coupling: if next item fits the post residual, reward smoothly
    if next_item_size > 0 {
        let gap = (rn - next_n).abs();
        let fit_bonus = if next_n <= rn {
            (1.0 - gap).max(0.0)
        } else {
            0.0
        };
        score -= 15.0 * fit_bonus * (1.0 + 0.5 * t) * (1.0 - rn);
    }

    // Mean residual coupling: bins far from the mean get a smooth penalty
    let mean_rn = mean_residual / cap;
    score += 8.0 * (rn - mean_rn) * (rn - mean_rn) * (1.0 + t);

    // Last-chance bin: smooth exponential reward when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - rn * rn).max(0.0);
    }

    // Slight preference to reuse existing bins vs opening new ones
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - rn) * 2.0;

    score
}

