    // still host a follow-up item after the next one lands, scaled by how
    // tight the remaining slack is (tight slack = high recombination odds).
    if next_item_size > 0 && next_item_size <= post_residual {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && (after_next as u32) >= next_item_size / 2 && (after_next as u32) <= next_item_size * 2 {
