        score += 8.0 * (1.0 - progress);
    }

    // Dead-space elimination sweep.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // Mid-residual band tightening — penalize 30-50 dead zone mid-stream.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead: next item lands residual within 2 units of zero.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // Near-exact fill escalation — tiny sliver residuals, scaled by alternatives.
    if post_residual > 0 && post_residual <= 4 {
        score -= (5.0 - post_residual as f64) * 10.0 * (1.0 + 0.5 * (1.0 - progress));
    }

    // Sliver-residual competition — prefer the bin whose leftover best chains
    // with the next item when multiple bins compete.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 {
        let next_f = next_item_size as f64;
        if pr >= next_f {
            let chain_eff = next_f / pr;
            score -= 6.0 * chain_eff * (1.0 - progress);
        }
    }

    // Residual-target alignment — reward leftovers matching the stream's
    // typical residual scale, improving future fit odds.
    if post_residual > 0 && mr > 1.0 {
        let band = ((pr - mr) / mr).abs();
        if band < 0.15 {
            score -= 5.0 * (1.0 - band / 0.15) * (1.0 - progress);
        }
    }

    // Dual-chain lookahead — reward bins where the next item fits AND the
    // leftover after it still exceeds the stream's mean demand.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let after_next = post_residual - next_item_size;
        if after_next as f64 >= mr && mr > 1.0 {
            score -= 7.0 * (1.0 - progress) * (1.0 - (after_next as f64 / cap).min(1.0));
        }
    }

    // Waste-floor compaction — graded penalty for near-dead bins.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual > 4 {
        score += 3.0 * (1.0 - pr / (next_item_size as f64)) * (1.0 - progress);
    }

    // Crowding-aware perfect-fill escalation.
    if post_residual == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // NEW (gen 21): compaction-coupled chain scoring — combine fine residual
    // fitting with forward anticipation: when the next item fits and the
    // after-next residual is small but nonzero, reward proportionally to
    // how much dead space the two-step chain eliminates from this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let after_next = (post_residual - next_item_size) as f64;
        let eliminated = (pr - after_next) / cap;
        if after_next <= 20.0 {
            score -= 9.0 * eliminated * (1.0 - after_next / 20.0) * (1.0 - progress);
        }
    }

    // NEW (gen 21): residual-variance-aware compaction — when the stream's
    // residual spread is tight (predictable), prefer bins whose post-residual
    // lands inside one item-size of the mean demand to enable chained fits.
    if post_residual > 0 && mr > 1.0 {
        let dist = (pr - mr).abs();
        if dist <= 10.0 {
            score -= 6.0 * (1.0 - dist / 10.0) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // NEW (gen 21): late-stream squeeze — with few items left, any leftover
    // capacity is likely wasted forever; penalize residuals aggressively
    // in proportion to remaining item count.
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    if remaining < 30.0 && post_residual > 0 {
        score += pr * (0.35 * (1.0 - remaining / 30.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight waste more heavily than pure residual.
    score += 0.5 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // --- 2-step lookahead: does the NEXT item fit into the post-residual? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can be chained here: reward proportional to how snugly it lands.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item would NOT fit after this placement: penalize, scaled by
            // how badly it misses (dead space the next item cannot use).
            let miss = (next_item_size - post_residual) as f64;
            score += 6.0 * (miss / bin_capacity as f64);
        }
    }

    // --- Relative-to-mean-residual coupling ---
    // Bins with residual far above the mean are "loose" — placing here is cheap
    // if the fit is tight; bins below the mean are precious — penalize waste.
    if post_residual as f64 > mean_residual {
        score += 0.25 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // --- Last-chance bin: if this is the ONLY bin that fits, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is good only if the current item is large or no
        // open bin gives a decent fit; otherwise keep fragmentation low.
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 1 && fit_ratio < 0.5 {
            score += 30.0; // discourage spreading when existing bins fit fine
        } else {
            score -= 10.0 * fit_ratio; // large items deserve fresh bins
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild preference to fill bins that are already mostly full (low residual).
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Sharpened quartic dead-space penalty (deepened further this generation).
    let dead = norm_pr.powi(3) * 24.0 + norm_pr.powi(4) * 18.0;
    score -= dead;
    if norm_pr < 0.15 && post_residual > 0 {
        score += (0.15 - norm_pr) * 95.0 * (1.0 - progress);
    }

    // Polynomial progress coupling.
    score += pr * (0.5 * progress * progress);

    // Relative fit quality vs mean residual.
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 10.0 * (1.0 - progress);

    // Lookahead chaining with two-step window.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fits = (post_residual - next_item_size) as f64;
            score -= fits * 0.3 * (1.0 - progress);
            if fits <= 8.0 {
                score -= 35.0 * (1.0 - fits / 8.0);
            }
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 24.0 * fit_ratio * (1.0 - progress);
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 12 {
                score -= 3.5 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
            }
            if after_next >= item_size {
                score -= 10.0;
            }
            if after_next >= next_item_size {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
            if gap <= 5.0 {
                score += 10.0 * (1.0 - gap / 5.0) * (1.0 - progress);
            }
        }
    } else {
        score -= 35.0 * (1.0 - norm_pr);
    }

