    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 22.0 * (fill - 0.75);
    }
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    }

    // Dead-residual band / perfect fill.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 8 {
        score += 60.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // Last-chance preference.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual consolidation.
    let dev = mean_residual - pr;
    score -= 0.22 * dev.clamp(-50.0, 50.0);

    // Open-bin pressure, smooth.
    score += open_bins_count as f64 * (1.2 + 1.8 * progress);
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // Granularity alignment.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Mid-band residual preference early in the stream.
    if norm_pr >= 0.25 && norm_pr <= 0.55 && progress < 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation guard.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Multi-fit competition term.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // Waste-aware residual bucket penalty.
    if post_residual > 0 && progress < 0.9 {
        let dead_zone = if post_residual < 24 { (post_residual as f64).min(24.0) / 24.0 } else { 0.0 };
        score += 9.0 * dead_zone * (1.0 - progress);
        if post_residual >= 25 && post_residual <= 60 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Tightness-of-fit variance reduction.
    if post_residual > 0 && mean_residual > 0.0 {
        let spread = ((pr - mean_residual) / mean_residual).abs();
        score += 4.0 * spread.min(2.0) * progress;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && item_size as f64 > 0.85 * cap && progress < 0.4 {
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64 - next_item_size as f64).max(0.0);
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress);
            }
            let fresh_full = (cap - item_size as f64).max(0.0);
            if fresh_full <= existing_res + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
            if fresh_res <= 10.0 && existing_res > 20.0 {
                score -= 20.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        if item_size == bin_capacity {
            score -= 120.0;
        }
        // Fresh-bin gate: open a fresh bin only when its post-fit residual
        // clearly dominates what any existing bin could leave.
        let fresh_after = (cap - item_size as f64).max(0.0);
        let best_existing_after = (mean_residual - item_size as f64).max(0.0);
        if fresh_after > best_existing_after + 8.0 {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
        // Guard against opening bins for small items late — consolidation
        // pressure scales with item smallness and stream progress.
        if item_size < 40 && progress > 0.45 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        // Prefer a fresh bin when the item would leave a large stranded
        // residual in every existing bin but fits snugly into a fresh one.
        if fitting_bins_count > 0 && item_size as f64 > 0.7 * cap {
            let snug = (cap - item_size as f64) <= 20.0;
            let stranded = mean_residual > item_size as f64 + 25.0;
            if snug && stranded {
                score -= 16.0 * (1.0 - progress);
            }
        }
        // NEW: two-step fresh-bin lookahead — if a fresh bin lets the next
        // item nearly fill it (pair within 4 of capacity) while existing bins
        // cannot chain, favor opening it early-to-mid stream.
        if next_item_size > 0 && fitting_bins_count > 0 && progress < 0.7 {
            let pair_gap = (item_size as f64 + next_item_size as f64) - cap;
            let existing_pair_gap = (mean_residual + next_item_size as f64) - cap;
            if pair_gap.abs() <= 4.0 && existing_pair_gap.abs() > pair_gap.abs() + 6.0 {
                score -= 20.0 * (1.0 - progress) * (1.0 - pair_gap.abs() / 4.0);
            }
        }
    }

    // Residual-hoarding penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size + 40 && progress < 0.8 {
        score += 6.0 * (1.0 - progress);
    }

    // Pair-completion bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0 * (1.0 - progress);
    }

    // Near-miss chain sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 4.0 {
            score += 14.0 * (1.0 - miss / 4.0) * (1.0 - progress);
        }
    }

    // Adaptive consolidation — late stream, close bins out aggressively.
    if progress > 0.7 && post_residual > 0 {
        score += pr * 0.25 * (progress - 0.7) / 0.3;
    }

    // Two-item chain packing: next item exactly filling the post-residual
    // closes this bin perfectly; reward scales with dead space eliminated.
    if post_residual > 0 && next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0 * (1.0 - norm_pr) * (1.0 - progress);
    }

    // Residual symmetry: multiples of 5 are likelier future item sizes.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.0 * (1.0 - progress);
    }

    // Large-item reservation: keep residual space for looming big items.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress);
    }

    // Dead-space elimination sweep — when the item consumes a residual
    // that would otherwise be stranded small, reward quadratically.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // Mid-residual band tightening — penalize residuals in the
    // 30-50 dead zone more strongly mid-stream, where they rarely refill.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead — if the next item lands the fresh/existing
    // residual within 2 units of zero, reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // NEW: triple-chain dead-space killer — when the current item plus next
    // two-step window can be anticipated to nearly close the bin, reward
    // proportionally to how close the projected residual is to zero.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && after_next <= 6 && progress < 0.8 {
            score -= 10.0 * (1.0 - after_next as f64 / 6.0) * (1.0 - progress);
        }
    }

    // NEW: residual-band harmonics — residuals in [12, 29] refill often for
    // common item sizes; mildly favor them mid-stream over 30-60 dead zone.
    if post_residual >= 12 && post_residual <= 29 && progress < 0.6 {
        score -= 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small waste relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * bin_capacity as f64;

    // Penalize dead space that can't fit typical future items (small residuals are traps).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here: mild penalty proportional to wasted opportunity.
            score += 3.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: empty bin should only win when fits elsewhere are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 30.0;
        // Cheaper to open a new bin early in the stream (long horizon amortizes it)
        // and when many open bins already exist (fragmentation pressure).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
        // If item fits snugly in a fresh bin (large item), opening is attractive.
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        if fit_ratio > 0.6 {
            score -= 12.0;
        }
        // If other bins exist that fit, discourage new bin unless they're all loose.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
        // If mean residual across open bins is large, open bins are roomy; avoid new bin.
        score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 25.0;
    } else {
        // Prefer fuller bins among open ones (best-fit bias beyond raw residual).
        score += (bin_residual as f64 - post_residual as f64) * 0.1;
        // Slight penalty for spreading across many bins when mean residual is low.
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

