        // sit just above the next item (small absorbable gap) with a
        // gap-scaled bonus, tightening dead-space ratio control.
        if next_item_size > 0 && r > next_item_size as f64 {
            let gap = r - next_item_size as f64;
            if gap <= 15.0 {
                score -= (10.0 - 0.5 * gap) * (1.0 - progress);
            }
        }
    }

    // GEN 22 refinement: two-item lookahead close-out.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // GEN 22 refinement: waste-rate coupling.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // GEN 23 mutation: fill-quality harmonic term — reward bins where the
    // item consumes a large fraction of the CURRENT residual, scaled by
    // remaining stream length, sharpening compaction on well-matched fits.
    if bin_residual > 0 && progress < 0.95 {
        let util = item_size as f64 / bin_residual as f64;
        if util > 0.6 {
            score -= 6.0 * (util - 0.6) * (1.0 - progress * 0.5);
        }
    }

    // GEN 23 mutation: stranded-sliver escalation — residuals below 6 after
    // placement are nearly unusable; penalize them more strongly mid-stream
    // unless the bin is now exactly full.
    if post_residual > 0 && post_residual < 6 && progress > 0.2 && progress < 0.8 {
        score += 12.0 * (1.0 - post_residual as f64 / 6.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
