    // Mid-residual band tightening — penalize 30-50 dead zone mid-stream.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead: next item lands residual within 2 units of zero.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // Near-exact fill escalation — tiny sliver residuals, scaled by alternatives.
    if post_residual > 0 && post_residual <= 4 {
        score -= (5.0 - post_residual as f64) * 10.0 * (1.0 + 0.5 * (1.0 - progress));
    }

    // Sliver-residual competition — prefer the bin whose leftover best chains
    // with the next item when multiple bins compete.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 {
        let next_f = next_item_size as f64;
        if pr >= next_f {
            let chain_eff = next_f / pr;
            score -= 6.0 * chain_eff * (1.0 - progress);
        }
    }

    // Residual-target alignment — reward leftovers matching the stream's
    // typical residual scale, improving future fit odds.
    if post_residual > 0 && mr > 1.0 {
        let band = ((pr - mr) / mr).abs();
        if band < 0.15 {
            score -= 5.0 * (1.0 - band / 0.15) * (1.0 - progress);
        }
    }

    // Dual-chain lookahead — reward bins where the next item fits AND the
    // leftover after it still exceeds the stream's mean demand.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let after_next = post_residual - next_item_size;
        if after_next as f64 >= mr && mr > 1.0 {
            score -= 7.0 * (1.0 - progress) * (1.0 - (after_next as f64 / cap).min(1.0));
        }
    }

    // Waste-floor compaction — graded penalty for near-dead bins.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual > 4 {
        score += 3.0 * (1.0 - pr / (next_item_size as f64)) * (1.0 - progress);
    }

    // Crowding-aware perfect-fill escalation.
    if post_residual == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // GEN 22: dead-space ratio shaping — U-curve rewarding residuals in the
    // 30..=60 sweet spot, penalizing stranded slivers and oversized leftovers.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 30.0).min(1.0);
        score -= 7.0 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // GEN 22: two-item lookahead — next item + mean demand nearly exhausts bin.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // GEN 22: waste-rate coupling — many open bins and low mean residual.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // GEN 23 (new): residual-reuse probability shaping — weight the post-fit
    // residual by how likely it matches upcoming item sizes; penalize sparse
    // high bands that rarely absorb future items.
    if post_residual > 0 && progress < 0.85 {
        let reuse = (post_residual.min(100) as f64) / 100.0;
        score -= 8.0 * reuse * (1.0 - progress);
        if post_residual > 70 {
            score += 10.0 * (1.0 - progress) * ((post_residual as f64 - 70.0) / 30.0).min(1.0);
        }
    }

    // GEN 23 (new): triple-chain lookahead — reward when the post-residual can
    // host the next item AND leave room matching the mean residual scale.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    score
}

