    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && item_size as f64 > 0.85 * cap && progress < 0.4 {
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64 - next_item_size as f64).max(0.0);
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress);
            }
            let fresh_full = (cap - item_size as f64).max(0.0);
            if fresh_full <= existing_res + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
            if fresh_res <= 10.0 && existing_res > 20.0 {
                score -= 20.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        if item_size == bin_capacity {
            score -= 120.0;
        }
        // Fresh-bin gate: open a fresh bin only when its post-fit residual
        // clearly dominates what any existing bin could leave.
        let fresh_after = (cap - item_size as f64).max(0.0);
        let best_existing_after = (mean_residual - item_size as f64).max(0.0);
        if fresh_after > best_existing_after + 8.0 {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
        // Consolidation pressure for small items late in the stream.
        if item_size < 40 && progress > 0.45 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        // Prefer a fresh bin when the item would leave a large stranded
        // residual in every existing bin but fits snugly into a fresh one.
        if fitting_bins_count > 0 && item_size as f64 > 0.7 * cap {
            let snug = (cap - item_size as f64) <= 20.0;
            let stranded = mean_residual > item_size as f64 + 25.0;
            if snug && stranded {
                score -= 16.0 * (1.0 - progress);
            }
        }
        // GEN 23: fresh-bin pair-completion — open a new bin when item+next
        // exactly or near-exactly fills capacity, avoiding a wasted slot.
        if next_item_size > 0 {
            let pair_slack = cap - item_size as f64 - next_item_size as f64;
            if pair_slack >= 0.0 && pair_slack <= 4.0 {
                score -= 22.0 * (1.0 - pair_slack / 4.0) * (1.0 - progress);
            }
        }
    }

    // Residual-hoarding penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size + 40 && progress < 0.8 {
        score += 6.0 * (1.0 - progress);
    }

    // Pair-completion bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0 * (1.0 - progress);
    }

    // Near-miss chain sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 4.0 {
            score += 14.0 * (1.0 - miss / 4.0) * (1.0 - progress);
        }
    }

    // Adaptive consolidation — late stream, close bins out aggressively.
    if progress > 0.7 && post_residual > 0 {
        score += pr * 0.25 * (progress - 0.7) / 0.3;
    }

    // Residual symmetry: multiples of 5 are likelier future item sizes.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.0 * (1.0 - progress);
    }

    // Large-item reservation.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress);
    }

    // Dead-space elimination sweep.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // Mid-residual dead-zone tightening.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // Residual-reuse probability shaping — weight the post-fit residual by
    // how likely it matches upcoming item sizes; penalize sparse high bands.
    if post_residual > 0 && progress < 0.85 {
        let reuse = (post_residual.min(100) as f64) / 100.0;
        score -= 8.0 * reuse * (1.0 - progress);
        if post_residual > 70 {
            score += 10.0 * (1.0 - progress) * ((post_residual as f64 - 70.0) / 30.0).min(1.0);
        }
    }

    // Triple-chain lookahead — reward when post-residual can host next item
    // AND leave room matching mean residual scale.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // GEN 22 refinement: dead-space ratio shaping — U-curve rewarding
    // residuals in the 30..=60 sweet spot; GEN 23 tunes the center
    // dynamically toward the mean residual so the sweet spot tracks the
    // actual stream distribution instead of a fixed 45.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let center = if mean_residual > 15.0 { mean_residual.clamp(25.0, 60.0) } else { 45.0 };
        let sweet = ((r - center).abs() / 30.0).min(1.0);
        score -= 8.0 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
        // GEN 23: penalize residuals that no plausible upcoming size can
        // absorb — stranded slivers below the running mean demand.
        if r < mean_residual * 0.35 && r < next_item_size as f64 {
            score += 6.0 * (1.0 - progress) * (1.0 - r / (mean_residual * 0.35).max(1.0));
        }
    }

    // GEN 22 refinement: two-item lookahead — when the next two logical
    // fills (next item + mean residual demand) nearly exhaust the bin,
    // strongly prefer closing it out.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // GEN 22 refinement: waste-rate coupling — when many bins are open and
    // mean residual is low, tighten preference for minimal post-residuals.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // GEN 23: bin-closing pressure — when the item nearly fills the bin
    // (tiny post-residual), reward extra strongly if it's the only fitting
    // bin, preventing pointless competition among near-full bins.
    if post_residual > 0 && post_residual <= 4 && fill > 0.95 {
        score -= 12.0 * (1.0 - post_residual as f64 / 4.0);
    }

    // GEN 23: split-fit avoidance — when the item leaves a post-residual
    // just barely below the next item size, penalize so the residual band
    // doesn't trap a near-miss item later.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss > 4.0 && miss <= 15.0 {
            score += 5.0 * (1.0 - progress) * (1.0 - miss / 15.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Sharpened dead-space penalty: cubic base with quartic deepening.
    let dead = norm_pr.powi(3) * 24.0 + norm_pr.powi(4) * 18.0;
    score -= dead;
    if norm_pr < 0.15 && post_residual > 0 {
        score += (0.15 - norm_pr) * 95.0 * (1.0 - progress);
    }

    // Polynomial progress coupling.
    score += pr * (0.5 * progress * progress);

    // Relative fit quality vs mean residual.
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 10.0 * (1.0 - progress);

    // Lookahead chaining with two-step window.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fits = (post_residual - next_item_size) as f64;
            score -= fits * 0.3 * (1.0 - progress);
            if fits <= 8.0 {
                score -= 38.0 * (1.0 - fits / 8.0);
            }
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 24.0 * fit_ratio * (1.0 - progress);
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 12 {
                score -= 3.5 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
            }
            if after_next >= item_size {
                score -= 10.0;
            }
            if after_next >= next_item_size {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
            if gap <= 5.0 {
                score += 10.0 * (1.0 - gap / 5.0) * (1.0 - progress);
            }
        }
    } else {
        score -= 35.0 * (1.0 - norm_pr);
    }

    // Tight-fill bonuses with exact-hit escalation.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 22.0 * (fill - 0.75);
    }
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    }

    // Dead-residual band / perfect fill.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 8 {
        score += 60.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // Last-chance preference.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual consolidation.
    let dev = mean_residual - pr;
    score -= 0.22 * dev.clamp(-50.0, 50.0);

    // Open-bin pressure, smooth.
    score += open_bins_count as f64 * (1.2 + 1.8 * progress);
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // Granularity alignment.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Mid-band residual preference early in the stream.
    if norm_pr >= 0.25 && norm_pr <= 0.55 && progress < 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation guard.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Multi-fit competition term.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // Waste-aware residual bucket penalty.
    if post_residual > 0 && progress < 0.9 {
        let dead_zone = if post_residual < 24 { (post_residual as f64).min(24.0) / 24.0 } else { 0.0 };
        score += 9.0 * dead_zone * (1.0 - progress);
        if post_residual >= 25 && post_residual <= 60 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Tightness-of-fit variance reduction.
    if post_residual > 0 && mean_residual > 0.0 {
        let spread = ((pr - mean_residual) / mean_residual).abs();
        score += 4.0 * spread.min(2.0) * progress;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && item_size as f64 > 0.85 * cap && progress < 0.4 {
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64 - next_item_size as f64).max(0.0);
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress);
            }
            let fresh_full = (cap - item_size as f64).max(0.0);
            if fresh_full <= existing_res + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
            if fresh_res <= 10.0 && existing_res > 20.0 {
                score -= 20.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        if item_size == bin_capacity {
            score -= 120.0;
        }
        // Fresh-bin gate: open a fresh bin only when its post-fit residual
        // clearly dominates what any existing bin could leave.
        let fresh_after = (cap - item_size as f64).max(0.0);
        let best_existing_after = (mean_residual - item_size as f64).max(0.0);
        if fresh_after > best_existing_after + 8.0 {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
        // Guard against opening bins for small items late.
        if item_size < 40 && progress > 0.45 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        // Two-item lookahead gate: pair fits almost perfectly in a fresh bin.
        if next_item_size > 0 {
            let pair_res = cap - item_size as f64 - next_item_size as f64;
            if pair_res >= 0.0 && pair_res <= 8.0 && progress < 0.85 {
                score -= 26.0 * (1.0 - pair_res / 8.0) * (1.0 - progress);
            }
        }
        // Snug-fit fresh-bin bonus.
        if fitting_bins_count > 0 && item_size as f64 > 0.7 * cap {
            let snug = (cap - item_size as f64) <= 20.0;
            let stranded = mean_residual > item_size as f64 + 25.0;
            if snug && stranded {
                score -= 16.0 * (1.0 - progress);
            }
        }
    }

    // Residual-hoarding penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size + 40 && progress < 0.8 {
        score += 6.0 * (1.0 - progress);
    }

    // Pair-completion bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0 * (1.0 - progress);
    }

    // Near-miss chain sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 4.0 {
            score += 14.0 * (1.0 - miss / 4.0) * (1.0 - progress);
        }
    }

    // Adaptive consolidation — late stream, close bins out aggressively.
    if progress > 0.7 && post_residual > 0 {
        score += pr * 0.25 * (progress - 0.7) / 0.3;
    }

    // Two-item chain packing: next item exactly filling the post-residual.
    if post_residual > 0 && next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0 * (1.0 - norm_pr) * (1.0 - progress);
    }

    // Residual symmetry: multiples of 5 are likelier future item sizes.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.0 * (1.0 - progress);
    }

    // Large-item reservation: keep residual space for looming big items.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress);
    }

    // Dead-space elimination sweep.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // Mid-residual band tightening — penalize 30-50 dead zone mid-stream.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead: next item lands residual within 2 units of zero.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // Near-exact fill escalation — tiny sliver residuals, scaled by alternatives.
    if post_residual > 0 && post_residual <= 4 {
        score -= (5.0 - post_residual as f64) * 10.0 * (1.0 + 0.5 * (1.0 - progress));
    }

    // Sliver-residual competition — prefer the bin whose leftover best chains
    // with the next item when multiple bins compete.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 {
        let next_f = next_item_size as f64;
        if pr >= next_f {
            let chain_eff = next_f / pr;
            score -= 6.0 * chain_eff * (1.0 - progress);
        }
    }

    // Residual-target alignment — reward leftovers matching the stream's
    // typical residual scale, improving future fit odds.
    if post_residual > 0 && mr > 1.0 {
        let band = ((pr - mr) / mr).abs();
        if band < 0.15 {
            score -= 5.0 * (1.0 - band / 0.15) * (1.0 - progress);
        }
    }

    // Dual-chain lookahead — reward bins where the next item fits AND the
    // leftover after it still exceeds the stream's mean demand.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let after_next = post_residual - next_item_size;
        if after_next as f64 >= mr && mr > 1.0 {
            score -= 7.0 * (1.0 - progress) * (1.0 - (after_next as f64 / cap).min(1.0));
        }
    }

    // Waste-floor compaction — graded penalty for near-dead bins.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && next_item_size - post_residual > 4 {
        score += 3.0 * (1.0 - pr / (next_item_size as f64)) * (1.0 - progress);
    }

    // Crowding-aware perfect-fill escalation.
    if post_residual == 0 && fitting_bins_count > 2 {
        score -= 12.0 * (1.0 - progress);
    }

    // GEN 23 (combined): U-curve residual-reuse shaping — reward the 30..=60
    // sweet spot (most likely to absorb a future item), penalize slivers and
    // oversized leftovers, weighted by mean-residual proximity.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 30.0).min(1.0);
        score -= 7.0 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
        let reuse = r.min(100.0) / 100.0;
        score -= 6.0 * reuse * (1.0 - progress);
        if r > 70 {
            score += 9.0 * (1.0 - progress) * ((r - 70.0) / 30.0).min(1.0);
        }
    }

    // GEN 23 (combined): two-item chain-to-closure — when next item plus
    // mean demand nearly exhausts the bin, prefer closing it out.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        let over = chain - pr;
        if over >= 0.0 && over <= 12.0 {
            score -= 11.0 * (1.0 - over / 12.0) * (1.0 - progress);
        }
    }

    // GEN 23 (combined): triple-chain lookahead — post-residual hosts next
    // item and leaves room matching mean residual scale.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // GEN 23: waste-rate coupling — many open bins with low mean residual
    // tightens preference for minimal post-residuals.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // GEN 23: fine-grained residual fitting fused with lookahead anticipation —
    // grade the fit by how tightly the next item nests, coupling the leftover
    // with the stream's expected demand so small residuals stay reusable.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let after_next = post_residual - next_item_size;
        let nest = next_item_size as f64 / pr;
        if after_next as f64 <= mr * 0.5 {
            score -= 5.0 * nest * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
