    // GEN 23: residual-versus-next-item surplus shaping — reward residuals
    // that host the next item with usable remainder, penalize residuals
    // that barely miss by a wide margin (near-certain future dead space).
    if next_item_size > 0 && post_residual > 0 && progress < 0.85 {
        let d = post_residual as i64 - next_item_size as i64;
        if d > 4 && d <= 20 {
            score -= 0.5 * d as f64 * (1.0 - progress);
        } else if d < -6 && d >= -25 {
            score += 0.4 * (-d) as f64 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
