        // fresh residual after the item is close to the next item size, i.e.
        // the fresh bin is likely to be completed exactly.
        if next_item_size > 0 {
            let fresh_pair_gap = (fresh_after - next_item_size as f64).abs();
            if fresh_pair_gap <= 3.0 {
