        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // Residual-reuse probability shaping.
    if post_residual > 0 && progress < 0.85 {
        let reuse = (post_residual.min(100) as f64) / 100.0;
        score -= 8.0 * reuse * (1.0 - progress);
        if post_residual > 70 {
            score += 10.0 * (1.0 - progress) * ((post_residual as f64 - 70.0) / 30.0).min(1.0);
        }
    }

    // Triple-chain lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // GEN 23 refinement: dead-space ratio shaping — U-curve rewarding the
    // 30..=60 sweet spot, penalizing tiny stranded slivers and oversized
    // leftovers; sliver penalty now scales with how far below the next item.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 30.0).min(1.0);
        score -= 7.0 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // GEN 23 refinement: two-item lookahead — when the next item plus mean
    // residual demand nearly exhausts the bin, prefer closing it out.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        let over = chain - pr;
        if over >= 0.0 && over <= 12.0 {
            score -= 11.0 * (1.0 - over / 12.0) * (1.0 - progress);
        }
    }

    // GEN 23 refinement: waste-rate coupling — many open bins with low mean
    // residual means fragmentation; tighten preference for minimal residuals.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // GEN 23: fit-ratio escalation — when the item consumes more than 85%
    // of the bin residual, add a quadratic reward to force near-closures
    // ahead of hoarding residuals for uncertain future fits.
    if fill > 0.85 && bin_residual != bin_capacity {
        score -= 12.0 * (fill - 0.85).powi(2) * 100.0 * (1.0 - progress);
    }

    // GEN 23: stranded-large-residual penalty — leaving a residual that no
    // plausible item (next or mean-scale) can absorb is pure waste.
    if post_residual > 0 && progress < 0.85 {
        let can_absorb = next_item_size as f64 <= pr
            || (mean_residual >= pr - 8.0 && mean_residual <= pr + 8.0);
        if !can_absorb && pr < cap * 0.6 {
            score += 9.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
