        if next_item_size > 0 && fitting_bins_count > 0 {
            let pair_slack = cap - item_size as f64 - next_item_size as f64;
            if pair_slack >= 0.0 && pair_slack <= 4.0 {
                score -= 26.0 * (1.0 - pair_slack / 4.0) * (1.0 - progress);
            }
        }
        // GEN 24: fresh-bin triple-exactness — open a new bin when item +
        // next + a mean-residual-scale item nearly close it out.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let triple = cap - item_size as f64 - next_item_size as f64 - mean_residual.max(0.0);
            if triple >= 0.0 && triple <= 5.0 {
                score -= 18.0 * (1.0 - triple / 5.0) * (1.0 - progress);
            }
        }
    }

    // Residual-hoarding penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size + 40 && progress < 0.8 {
        score += 6.0 * (1.0 - progress);
    }

    // Pair-completion bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0 * (1.0 - progress);
    }

    // Near-miss chain sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 4.0 {
            score += 14.0 * (1.0 - miss / 4.0) * (1.0 - progress);
        }
    }

    // Adaptive consolidation — late stream, close bins out aggressively.
    if progress > 0.7 && post_residual > 0 {
        score += pr * 0.25 * (progress - 0.7) / 0.3;
    }

    // Residual symmetry: multiples of 5 are likelier future item sizes.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.0 * (1.0 - progress);
    }

    // Large-item reservation.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress);
    }

    // Dead-space elimination sweep.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // Mid-residual dead-zone tightening.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // Residual-reuse probability shaping.
    if post_residual > 0 && progress < 0.85 {
        let reuse = (post_residual.min(100) as f64) / 100.0;
        score -= 8.0 * reuse * (1.0 - progress);
        if post_residual > 70 {
            score += 10.0 * (1.0 - progress) * ((post_residual as f64 - 70.0) / 30.0).min(1.0);
        }
    }

    // Triple-chain lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // GEN 23: sharpened U-curve dead-space shaping.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 40.0).abs() / 25.0).min(1.0);
        score -= 9.0 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // GEN 23: two-item lookahead closure bonus.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // GEN 23: waste-rate coupling under crowding.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // GEN 23: residual-versus-next-item surplus shaping.
    if next_item_size > 0 && post_residual > 0 && progress < 0.85 {
        let d = post_residual as i64 - next_item_size as i64;
        if d > 4 && d <= 20 {
            score -= 0.5 * d as f64 * (1.0 - progress);
        } else if d < -6 && d >= -25 {
            score += 0.4 * (-d) as f64 * (1.0 - progress);
        }
    }

    // GEN 24: fine-grained residual fitting — when the item fills the bin
    // to a residual that matches the next item within 1 unit, treat it as
    // an exact handoff and reward it strongly (combines residual fitting
    // with lookahead anticipation).
    if next_item_size > 0 && post_residual > 0 && progress < 0.9 {
        let handoff = (post_residual as i64 - next_item_size as i64).abs();
        if handoff <= 1 {
            score -= 24.0 * (1.0 - progress);
        }
    }

    // GEN 24: dead-space ratio guard — penalize bins whose post-fit
    // residual is a large fraction of capacity but cannot host the next
    // item; those fragments are near-certain waste.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let frag = pr / cap;
        if frag > 0.2 {
            score += 20.0 * frag * (1.0 - progress);
        }
    }

    // GEN 24: multi-item demand matching — when several bins can fit the
    // item, prefer the one whose residual best absorbs the mean demand
    // after this placement (reduces aggregate dead space).
    if fitting_bins_count > 2 && post_residual > 0 && progress < 0.8 {
        let demand_gap = ((pr - mean_residual) / 10.0).abs();
        score -= 5.0 * (1.0 - demand_gap.min(1.0)) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
