        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && item_size as f64 > 0.85 * cap && progress < 0.4 {
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64 - next_item_size as f64).max(0.0);
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress);
            }
            let fresh_full = (cap - item_size as f64).max(0.0);
            if fresh_full <= existing_res + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
            if fresh_res <= 10.0 && existing_res > 20.0 {
                score -= 20.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        if item_size == bin_capacity {
            score -= 120.0;
        }
        // Fresh-bin gate: open a fresh bin only when its post-fit residual
        // clearly dominates what any existing bin could leave.
        let fresh_after = (cap - item_size as f64).max(0.0);
        let best_existing_after = (mean_residual - item_size as f64).max(0.0);
        if fresh_after > best_existing_after + 8.0 {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
        // Consolidation pressure for small items late in the stream.
        if item_size < 40 && progress > 0.45 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        // Prefer a fresh bin when the item would leave a large stranded
        // residual in every existing bin but fits snugly into a fresh one.
        if fitting_bins_count > 0 && item_size as f64 > 0.7 * cap {
            let snug = (cap - item_size as f64) <= 20.0;
            let stranded = mean_residual > item_size as f64 + 25.0;
            if snug && stranded {
                score -= 16.0 * (1.0 - progress);
            }
        }
    }

    // Residual-hoarding penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size + 40 && progress < 0.8 {
        score += 6.0 * (1.0 - progress);
    }

    // Pair-completion bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0 * (1.0 - progress);
    }

    // Near-miss chain sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 4.0 {
            score += 14.0 * (1.0 - miss / 4.0) * (1.0 - progress);
        }
    }

    // Adaptive consolidation — late stream, close bins out aggressively.
    if progress > 0.7 && post_residual > 0 {
        score += pr * 0.25 * (progress - 0.7) / 0.3;
    }

    // Residual symmetry: multiples of 5 are likelier future item sizes.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.0 * (1.0 - progress);
    }

    // Large-item reservation.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress);
    }

    // Dead-space elimination sweep.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // Mid-residual dead-zone tightening.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // Residual-reuse probability shaping.
    if post_residual > 0 && progress < 0.85 {
        let reuse = (post_residual.min(100) as f64) / 100.0;
        score -= 8.0 * reuse * (1.0 - progress);
        if post_residual > 70 {
            score += 10.0 * (1.0 - progress) * ((post_residual as f64 - 70.0) / 30.0).min(1.0);
        }
    }

    // Triple-chain lookahead — reward when post-residual can host next item
    // AND leave room matching mean residual scale.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // GEN 25 refinement: next-aware dead-space sweet spot — the U-curve
    // center now tracks the next item size, so residuals most likely to
    // absorb the upcoming item are rewarded dynamically rather than at a
    // fixed 45-point anchor. Also sharpens sliver penalties.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let anchor = if next_item_size > 0 {
            ((next_item_size as f64 + 20.0) / 2.0).clamp(25.0, 55.0)
        } else {
            45.0
        };
        let sweet = ((r - anchor).abs() / 30.0).min(1.0);
        score -= 8.5 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // GEN 25 refinement: two-item lookahead — when the next two logical
    // fills (next item + mean residual demand) nearly exhaust the bin,
    // strongly prefer closing it out.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr as f64 && chain - pr as f64 <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr as f64) / 12.0) * (1.0 - progress);
        }
    }

    // GEN 25 refinement: waste-rate coupling — when many bins are open and
    // mean residual is low, tighten preference for minimal post-residuals.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // GEN 25 refinement: dead-space ratio guard — penalize residuals that
    // exceed both the next item and the mean demand band, i.e. space that
    // is unlikely to ever be reclaimed, with a progress-scaled weight.
    if post_residual > 0 && next_item_size > 0 && progress < 0.85 {
        let reclaimable = (post_residual as f64 - next_item_size as f64).max(0.0)
            .min((post_residual as f64 - mean_residual.max(0.0)).max(0.0));
        if reclaimable == 0.0 && post_residual > next_item_size {
            score += 5.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" is the leftover space.
    // Leftovers divisible by common small item sizes (multiples of 10/20/25) are valuable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 25 == 0 {
        -25.0
    } else if pr % 20 == 0 {
        -20.0
    } else if pr % 10 == 0 {
        -15.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0 // awkward leftover
    };
    score += harmonic_bonus;

    // Integer-division thresholds: classify leftover into dead-space zones.
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    if pr < quarter / 2 {
        score += 18.0; // tiny sliver, nearly dead
    } else if pr < quarter {
        score += 4.0;
    } else if pr < half {
        score -= 5.0; // mid leftover is quite usable
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact-class match is golden
            if pr % next_item_size.max(1) == 0 {
                score -= 22.0;
            } else {
                score -= 10.0;
            }
        } else {
            score += 12.0; // next item cannot use this bin's leftover
        }
    } else {
        // last item: prefer tight packing
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive unless
    // current leftovers are all poor fits (high mean fragmentation).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (post_residual as f64)) / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64 / (step_index.max(1) as f64);
        // open a new bin when existing bins are fragmented or few remain usable
        let penalty = 35.0 - 25.0 * fragmentation - 20.0 * (1.0 - openness).min(1.0) - 10.0 * progress;
        score += penalty.max(2.0);
    }

    // Mild preference to consolidate into fewer bins early on.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
