    // Triple-chain lookahead — reward when post-residual can host next item
    // AND leave room matching mean residual scale.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // GEN 22 refinement: dead-space ratio shaping — U-curve rewarding
    // residuals in the 30..=60 sweet spot, penalizing stranded slivers
    // and oversized leftovers.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 30.0).min(1.0);
        score -= 7.0 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // GEN 22 refinement: two-item lookahead — close bins whose next fill
    // plus mean demand nearly exhausts the bin.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // GEN 22 refinement: waste-rate coupling — many open bins with low mean
    // residual tighten preference for minimal post-residuals.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // GEN 25: dead-space ratio sharpening — strengthen the U-curve weight
    // slightly and add a hard penalty for leaving residuals that are just
    // barely too small to host the next item (the worst kind of waste).
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 28.0).min(1.0);
        score -= 2.5 * (1.0 - sweet) * (1.0 - progress);
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 4.0 * (1.0 - miss / 10.0) * (1.0 - progress);
        }
    }

    // GEN 25: late-stream exact-closure — when the next item would exactly
    // exhaust this bin's residual, treat it as a near-perfect fill.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible future item are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 30.0;
    } else {
        // Smoothly penalize residual space that cannot fit the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0;
        }
        // Mild non-linear reward for leaving large, reusable gaps.
        score -= (post_residual as f64 / bin_capacity as f64).powf(2.0) * 8.0;
    }

    // Lookahead coupling: strongly reward bins whose post-residual exactly
    // accommodates the next item (chain-fitting).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: discourage spreading across many bins when the item
    // fits well elsewhere; encourage using existing bins when many are open.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only allow opening a new bin when current bins have
    // poor fit potential; otherwise penalize the empty-bin candidate.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with sharpened non-linear dead-space penalty.
    let mut score = pr;
    let dead = norm_pr.powi(3) * 24.0 + norm_pr.powi(4) * 18.0;
    score -= dead;
    if norm_pr < 0.15 && post_residual > 0 {
        score += (0.15 - norm_pr) * 95.0 * (1.0 - progress);
    }

    // Polynomial progress coupling.
    score += pr * (0.5 + 0.5 * progress * progress) - 0.5 * pr;

    // Relative fit quality vs mean residual.
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 10.0 * (1.0 - progress);

