        // fills it almost exactly — a guaranteed two-item closure.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let pair_slack = cap - item_size as f64 - next_item_size as f64;
            if pair_slack >= 0.0 && pair_slack <= 4.0 {
