    // Triple-chain lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // GEN 26: combined U-curve dead-space shaping — sweet spot centered at
    // 42 with a tighter band, merging parent's dual U-curves into one.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 42.0).abs() / 26.0).min(1.0);
        score -= 11.0 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // GEN 26: two-item lookahead closure bonus.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // GEN 26: waste-rate coupling under crowding.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // GEN 26: residual-versus-next-item surplus shaping.
    if next_item_size > 0 && post_residual > 0 && progress < 0.85 {
        let d = post_residual as i64 - next_item_size as i64;
        if d > 4 && d <= 20 {
            score -= 0.5 * d as f64 * (1.0 - progress);
        } else if d < -6 && d >= -25 {
            score += 0.4 * (-d) as f64 * (1.0 - progress);
        }
    }

    // GEN 26: fine-grained residual fitting — reward residuals within a
    // tight window of the next item's size (high reuse probability) with a
    // smooth quadratic kernel, complementing the hard near-miss bands.
    if next_item_size > 0 && post_residual > 0 && progress < 0.9 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        if diff <= 15.0 {
            score -= 0.06 * (15.0 - diff) * (15.0 - diff) * (1.0 - progress);
        }
    }

    score
}

