    }

    // GEN 25: late-stream exact-closure — when the next item would exactly
    // exhaust this bin's residual, treat it as a near-perfect fill.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 12.0 * progress;
    }

    // GEN 26: stranded-sliver penalty escalation — a residual that is a
    // near-miss for the next item is the worst waste; escalate the penalty
    // when many bins are open (slivers are less likely to be reused).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 && open_bins_count > 2 {
            score += 5.0 * (1.0 - miss / 6.0) * (1.0 - progress) * (open_bins_count as f64).min(6.0) / 6.0;
        }
    }

    // GEN 26: compaction coupling — reward placements that drive the bin's
    // residual toward the mean residual scale (harmonized pool of leftovers),
    // slightly stronger mid-stream where consolidation matters most.
    if post_residual > 0 && mean_residual > 0.0 {
        let harmon = 1.0 - ((pr - mean_residual) / (mean_residual + 15.0)).abs().min(1.0);
        score -= 5.0 * harmon * (1.0 - (2.0 * progress - 1.0).abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
