        let reuse = (post_residual.min(100) as f64) / 100.0;
        score -= 8.0 * reuse * (1.0 - progress);
        if post_residual > 70 {
            score += 10.0 * (1.0 - progress) * ((post_residual as f64 - 70.0) / 30.0).min(1.0);
        }
    }

    // Triple-chain lookahead — reward when post-residual can host next item
    // AND leave room matching mean residual scale.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // Dead-space ratio shaping — U-curve rewarding residuals in the
    // 30..=60 sweet spot, penalizing stranded slivers and oversized leftovers.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 30.0).min(1.0);
        score -= 7.0 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Two-item lookahead — close bins whose next fill plus mean demand
    // nearly exhausts the bin.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // Waste-rate coupling — many open bins with low mean residual tighten
    // preference for minimal post-residuals.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // Dead-space ratio sharpening — strengthen the U-curve weight slightly
    // and add a hard penalty for leaving residuals that are just barely too
    // small to host the next item (the worst kind of waste).
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 28.0).min(1.0);
        score -= 2.5 * (1.0 - sweet) * (1.0 - progress);
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 4.0 * (1.0 - miss / 10.0) * (1.0 - progress);
        }
    }

    // Late-stream exact-closure — when the next item would exactly exhaust
    // this bin's residual, treat it as a near-perfect fill.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 12.0 * progress;
    }

    // GEN 26: residual-utilization coupling — couple the post-fit residual
    // to the running mean residual with a quadratic pull: residuals close
    // to the mean are most likely to be consumed by future items, so reward
    // that band more sharply than the fixed U-curve, especially mid-stream.
    if post_residual > 0 && progress > 0.1 && progress < 0.95 {
        let band = ((pr - mr) / 18.0).abs().min(2.0);
        score -= 5.5 * (1.0 - band / 2.0) * (1.0 - progress) * (0.5 + 0.5 * (mr / cap).min(1.0));
    }

    // GEN 26: two-item exact-completion sweep — when the next two expected
    // demands (next item + mean residual) exactly consume the bin, prefer
    // closing it now to avoid stranding a small remainder.
    if next_item_size > 0 && post_residual > 0 {
        let two = next_item_size as f64 + mr;
        let over = two - pr;
        if over >= 0.0 && over <= 3.0 {
            score -= 8.0 * (1.0 - over / 3.0) * (1.0 - progress);
        }
    }

    // GEN 26: oversized-leftover escalation — residuals above the largest
    // plausible next item (100) can never be fully consumed; penalize the
    // unusable fraction quadratically.
    if post_residual > 100 {
        let unusable = (post_residual - 100) as f64;
        score += 0.8 * unusable * (1.0 - progress);
    }

    score
}

