        if miss <= 10.0 {
            score += 5.0 * (1.0 - miss / 10.0) * (1.0 - progress);
        }
    }

    // GEN 26 (from best): late-stream exact-closure — next item exactly
    // exhausts this bin's residual is a near-perfect fill.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 12.0 * progress;
    }

    score
}

