    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 5.0 * (1.0 - miss / 10.0) * (1.0 - progress);
        }
    }

    // GEN 27 refinement: late-stream exact-closure — when the next item
    // would exactly exhaust this bin's residual, treat it as near-perfect.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 14.0 * progress;
    }

    // GEN 27 refinement: residual-versus-next surplus shaping sharpened —
    // widen the reward band for residuals hosting next with usable slack,
    // and penalize wide near-misses harder under crowding pressure.
    if next_item_size > 0 && post_residual > 0 && progress < 0.85 {
        let d = post_residual as i64 - next_item_size as i64;
        if d > 4 && d <= 28 {
            score -= 0.55 * d as f64 * (1.0 - progress);
        } else if d < -6 && d >= -30 {
            score += 0.45 * (-d) as f64 * (1.0 - progress) * (1.0 + 0.3 * open_bins_count.min(10) as f64 / 10.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
