    }

    // GEN 25: dead-space ratio sharpening — strengthen the U-curve weight
    // slightly and add a hard penalty for leaving residuals that are just
    // barely too small to host the next item (the worst kind of waste).
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 28.0).min(1.0);
