    // Sharpened U-curve dead-space shaping.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 40.0).abs() / 25.0).min(1.0);
        score -= 9.0 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Two-item lookahead closure bonus.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // Waste-rate coupling under crowding.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // Residual-versus-next-item surplus shaping.
    if next_item_size > 0 && post_residual > 0 && progress < 0.85 {
        let d = post_residual as i64 - next_item_size as i64;
        if d > 4 && d <= 28 {
            score -= 0.55 * d as f64 * (1.0 - progress);
        } else if d < -6 && d >= -30 {
            score += 0.45 * (-d) as f64 * (1.0 - progress) * (1.0 + 0.3 * open_bins_count.min(10) as f64 / 10.0);
        }
    }

    // Hard penalty for residuals just barely too small to host the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 5.0 * (1.0 - miss / 10.0) * (1.0 - progress);
        }
    }

    // Late-stream exact-closure — when the next item would exactly exhaust
    // this bin's residual, treat it as near-perfect.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 14.0 * progress;
    }

    // GEN 28 (combined from best lineage): residual-similarity tie-break —
    // among comparable fits, prefer the bin whose post-residual most closely
    // matches the running mean residual, reducing residual variance and
    // preserving future-fit flexibility.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let sim = 1.0 - ((pr - mean_residual) / (mean_residual + 20.0)).abs().min(1.0);
        score -= 6.0 * sim * (1.0 - progress);
    }

    // GEN 28 (combined from best lineage): bin-closure momentum — reward
    // near-exhausting fits to close bins out, weighted by progress.
    if post_residual > 0 && open_bins_count > 1 && item_size as f64 >= 0.85 * bin_residual as f64 {
        score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_residual.max(1) as f64);
    }

