            score -= 0.55 * d as f64 * (1.0 - progress);
        } else if d < -6 && d >= -30 {
            score += 0.45 * (-d) as f64 * (1.0 - progress) * (1.0 + 0.3 * open_bins_count.min(10) as f64 / 10.0);
        }
    }

    // GEN 27 refinement: hard penalty for residuals just barely too small
    // to host the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 5.0 * (1.0 - miss / 10.0) * (1.0 - progress);
        }
    }

    // GEN 27 refinement: late-stream exact-closure.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 14.0 * progress;
    }

    // GEN 28: residual-similarity tie-break — among comparable fits, prefer
    // the bin whose post-residual most closely matches the running mean
    // residual, reducing residual variance across open bins.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let sim = 1.0 - ((pr - mean_residual) / (mean_residual + 20.0)).abs().min(1.0);
        score -= 6.0 * sim * (1.0 - progress);
    }

    // GEN 28: bin-closure momentum — reward near-exhausting fits so bins
    // close out rather than lingering as fragmented half-full bins.
    if post_residual > 0 && open_bins_count > 1 && item_size as f64 >= 0.85 * bin_residual as f64 {
        score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // GEN 28: combined lookahead-consolidation coupling — when the next
    // item fits the post-residual AND the leftover aligns with mean demand,
    // reward proportionally to remaining stream (fine residual fitting +
    // lookahead anticipation fused).
    if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        let after = (post_residual - next_item_size) as f64;
        let align = 1.0 - ((after - mean_residual) / (mean_residual + 15.0)).abs().min(1.0);
        score -= 7.0 * align * (1.0 - progress);
        if after == 0.0 {
            score -= 8.0 * (1.0 - progress);
        }
    }

    score
}

