    if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        let after = post_residual - next_item_size;
        if after > 0 && (after as f64) < 0.35 * mean_residual.max(1.0) {
            score += 5.0 * (1.0 - progress);
        }
        if after >= 10 && (after as f64 - mean_residual.max(1.0)).abs() <= 10.0 {
            score -= 4.0 * (1.0 - progress);
        }
    }

    // GEN 29: open-bin count-aware tightening — with many open bins, prefer
    // the fit that most reduces residual variance across the fleet.
    if open_bins_count > 4 && post_residual > 0 && mean_residual > 0.0 {
        let var_pen = ((pr - mean_residual) / (mean_residual + 15.0)).abs();
        score += 3.0 * var_pen * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
