        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 30.0).min(1.0);
        score -= 7.0 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // GEN 22 refinement: two-item lookahead — close bins whose next fill
    // plus mean demand nearly exhausts the bin.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // GEN 22 refinement: waste-rate coupling — many open bins with low mean
    // residual tighten preference for minimal post-residuals.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
