    // exhaust this bin's residual, treat it as a near-perfect fill.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 12.0 * progress;
    }

    // GEN 27: residual-similarity tie-break — among comparable fits, prefer
    // the bin whose post-residual most closely matches the running mean
    // residual, reducing residual variance across open bins.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let sim = 1.0 - ((pr - mean_residual) / (mean_residual + 20.0)).abs().min(1.0);
        score -= 6.0 * sim * (1.0 - progress);
    }

    // GEN 27: bin-closure momentum — when few bins remain open relative to
    // stream length, reward near-exhausting fits to close bins out.
    if post_residual > 0 && open_bins_count > 1 && item_size as f64 >= 0.85 * bin_residual as f64 {
        score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // GEN 29: dead-space ratio refinement — sharpen the U-curve center
    // toward residual values that best match the empirical item-size scale
    // (half-capacity sweet spot), and penalize residuals just below the
    // mean item demand, which are the least reusable leftovers.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let center = (cap * 0.5).max(30.0).min(60.0);
        let sweet = ((r - center).abs() / (center * 0.6)).min(1.0);
        score -= 3.0 * (1.0 - sweet) * (1.0 - progress);
        if next_item_size > 0 && r < next_item_size as f64 && next_item_size as f64 - r <= 6.0 {
            score += 6.0 * (1.0 - (next_item_size as f64 - r) / 6.0) * (1.0 - progress);
        }
    }

    // GEN 29: capacity-fraction coupling — reward fits whose post-residual,
    // as a fraction of capacity, aligns with the item's own capacity
    // fraction (self-similar packing leaves balanced leftovers).
    if post_residual > 0 && progress < 0.85 {
        let item_frac = item_size as f64 / cap;
        let res_frac = norm_pr;
        let align = 1.0 - (item_frac - res_frac).abs();
        if align > 0.75 {
            score -= 5.0 * (align - 0.75) * 4.0 * (1.0 - progress);
        }
    }

    score
}

