    // residuals in the 30..=60 sweet spot, penalizing stranded slivers
    // and oversized leftovers.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 30.0).min(1.0);
        score -= 7.0 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // GEN 22 refinement: two-item lookahead — close bins whose next fill
    // plus mean demand nearly exhausts the bin.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // GEN 22 refinement: waste-rate coupling.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // GEN 25: dead-space ratio sharpening.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 28.0).min(1.0);
        score -= 2.5 * (1.0 - sweet) * (1.0 - progress);
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 4.0 * (1.0 - miss / 10.0) * (1.0 - progress);
        }
    }

    // GEN 25: late-stream exact-closure.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 12.0 * progress;
    }

    // GEN 27: residual-similarity tie-break.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let sim = 1.0 - ((pr - mean_residual) / (mean_residual + 20.0)).abs().min(1.0);
        score -= 6.0 * sim * (1.0 - progress);
    }

    // GEN 27: bin-closure momentum.
    if post_residual > 0 && open_bins_count > 1 && item_size as f64 >= 0.85 * bin_residual as f64 {
        score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // GEN 29: dead-space ratio refinement — sharpen the residual U-curve
    // around the empirical sweet spot and penalize residuals that are
    // large but too small for the next item (unusable mid-band waste).
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 42.0).abs() / 26.0).min(1.0);
        score -= 3.0 * (1.0 - sweet) * (1.0 - progress);
        if next_item_size > 0 && r < next_item_size as f64 && r >= 20.0 {
            score += 6.0 * (1.0 - progress) * (1.0 - (next_item_size - post_residual) as f64 / 40.0).max(0.0);
        }
    }

    // GEN 29: residual-entropy shaping — reward residuals close to the
    // running mean demand (maximizes chance of future reuse), penalize
    // outliers in either direction more strongly mid-stream.
    if post_residual > 0 && mean_residual > 0.0 {
        let outlier = ((pr - mean_residual) / (mean_residual + 15.0)).abs();
        score += 5.0 * outlier.min(2.0) * (0.5 + 0.5 * (1.0 - progress));
    }

    // GEN 29: near-exact two-item closure lookahead — when next item plus
    // a typical follow-up (mean residual) would finish the bin, prefer it.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let after = (post_residual - next_item_size) as f64;
        if after <= 15.0 && after >= mean_residual - 6.0 {
            score -= 7.0 * (1.0 - progress) * (1.0 - after / 15.0);
        }
    }

    score
}

