        } else if d < -6 && d >= -30 {
            score += 0.45 * (-d) as f64 * (1.0 - progress) * (1.0 + 0.3 * open_bins_count.min(10) as f64 / 10.0);
        }
    }

    // GEN 27 refinement: hard penalty for residuals just barely too small
    // to host the next item (worst kind of near-miss waste).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
