        }
    }

    // GEN 27 refinement: late-stream exact-closure — when the next item
    // would exactly exhaust this bin's residual, treat it as near-perfect.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 14.0 * progress;
    }

    // GEN 30 refinement (borrowed from best lineage): residual-similarity
    // tie-break — among comparable fits, prefer the bin whose post-residual
    // most closely matches the running mean residual, reducing residual
    // variance across open bins.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let sim = 1.0 - ((pr - mean_residual) / (mean_residual + 20.0)).abs().min(1.0);
        score -= 6.0 * sim * (1.0 - progress);
    }

    // GEN 30 refinement (borrowed from best lineage): bin-closure momentum —
    // when multiple bins are open, reward near-exhausting fits to close
