        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 7.0 * (1.0 - miss / 6.0) * (1.0 - progress);
        }
    }

    // GEN 30: dead-space ratio refinement — the diagnosed weakness is
    // suboptimal residual/dead-space ratio. Sharpen the U-curve sweet spot
