    // near mean_residual leaves the least expected future waste, so reward
    // proximity to (mean_residual + 5) in addition to the fixed band.
    if post_residual > 0 && mean_residual > 0.0 && progress < 0.85 {
        let target = (mean_residual + 5.0).clamp(20.0, 60.0);
        let prox = 1.0 - ((pr - target) / 30.0).abs().min(1.0);
