        // dead space — penalize proportionally.
        if pr > 2.0 * mean_residual + 15.0 {
            score += 5.0 * (1.0 - progress) * ((pr - (2.0 * mean_residual + 15.0)) / 40.0).min(1.0);
        }
    }

    // GEN 30: residual-quota balance — when several bins are open, avoid
    // concentrating all slack in one bin; prefer the fit whose post-residual
    // keeps the open-bin residual spread minimal.
    if post_residual > 0 && open_bins_count > 2 && progress < 0.8 {
        let ideal = mean_residual.max(10.0);
        let skew = ((pr - ideal) / ideal).abs().min(1.5);
        score += 3.5 * skew * (1.0 - progress);
    }

    score
}

