        if r > 65.0 {
            score += 6.0 * (1.0 - progress) * ((r - 65.0) / 35.0).min(1.0);
        }
    }

    // GEN 31: exact-closure escalation — when the next item exactly
    // exhausts the residual late in the stream, escalate the bonus so the
    // bin is closed rather than left as dead space.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 8.0 * (progress - 0.5);
    }

    // GEN 31: near-exact slack tightening — reward fits leaving 1..=5 slack
    // more strongly across the whole stream to squeeze out residual waste.
    if post_residual > 0 && post_residual <= 5 {
        score -= 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.4 + 0.6 * (1.0 - progress));
    }

    score
}

