            let closeness = 1.0 - ((after_next as f64 - mean_residual) / (mean_residual + 10.0)).abs().min(1.0);
            score -= 5.0 * closeness * (1.0 - progress);
            // Triple-chain: post-residual close to mean residual after chain.
            if (after_next as f64 - mean_residual).abs() <= 5.0 {
                score -= 9.0 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
