    // can absorb the next item AND whose resulting leftover still matches
    // the mean residual demand, favoring chains of reusable fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if after > 0 && (after as f64 - mean_residual).abs() <= 10.0 {
            score -= 5.0 * (1.0 - (after as f64 - mean_residual).abs() / 10.0) * (1.0 - progress);
        }
    }

