    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && next_item_size <= 30 && progress < 0.75 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 7.0 * (1.0 - miss / 6.0) * (1.0 - progress);
        }
    }

    // GEN 32: exact-hit escalation — reward fills that exhaust the bin within
    // a 3-unit slack window, closing bins outright.
    if slack >= 0.0 && slack <= 3.0 && progress > 0.4 {
        score -= 12.0 * progress;
    }

    score
}

