    // against the bin's original residual and penalize fits that strand a
    // large fraction of usable space, while rewarding fits that consume
    // most of the bin's remaining room even when the absolute leftover is
    // non-trivial. This targets the diagnosed weakness directly.
    if bin_residual > item_size && post_residual > 0 && progress < 0.9 {
        let consumed_ratio = item_size as f64 / bin_residual as f64;
        if consumed_ratio < 0.5 {
            // Leaving more than half the bin's remaining space stranded.
            score += 10.0 * (0.5 - consumed_ratio) * (1.0 - progress);
        } else if consumed_ratio > 0.8 {
            // Consuming most of the remaining space is valuable even if the
            // absolute leftover is moderate — reward it.
            score -= 8.0 * (consumed_ratio - 0.8) * (1.0 - progress);
        }
        // GEN 33: complementary — when the stranded leftover cannot serve
        // the next item nor a typical mean-residual demand, penalize harder.
        let unusable = post_residual < next_item_size
            && (pr < mr * 0.5 || pr > mr * 2.0);
        if unusable && consumed_ratio < 0.7 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // GEN 33: dual-residual balance — when the next item fits, prefer the
    // option whose post-residual best matches the *next* item's complement,
    // i.e. post_residual close to (mean_residual - next_item) so the chain
    // continues smoothly across bins.
    if next_item_size > 0 && next_item_size <= post_residual && mean_residual > next_item_size as f64 {
        let target = mean_residual - next_item_size as f64;
        let after = (post_residual - next_item_size) as f64;
        let align = 1.0 - ((after - target) / (target + 15.0)).abs().min(1.0);
        score -= 5.0 * align * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Primary reward: tight fits. Exponential decay of score as post_residual -> 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Reward near-perfect fits especially strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // heavily favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: with many open bins, prefer consolidating into
    // bins with below-average residual (i.e., nearly full bins).
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap;

    // When many bins are open, discourage spreading into emptier bins.
    if open_bins_count > 3 {
        score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Time horizon: late in the stream, be conservative — favor using
    // existing bins and avoid opening new ones (new-bin candidate gets
    // penalized more as progress -> 1).
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        // Base cost of opening a new bin, scaled by stream progress and
        // by how many bins are already open.
        let mut open_cost = 45.0 + 60.0 * progress + 2.0 * open_bins_count as f64;
        // Early in the stream, opening fresh bins is cheap so future items
        // have room; also cheap if item is large (poor fit anywhere).
        if progress < 0.2 {
            open_cost -= 25.0;
        }
        if item_size >= 70 {
            open_cost -= 20.0;
        }
        // If next item is large and this item is large, a fresh bin keeps
        // flexibility for the lookahead.
        if next_item_size >= 60 && item_size >= 50 {
            open_cost -= 15.0;
        }
        score += open_cost;
    }

    // Global residual balance: if mean residual is high (lots of slack
    // overall), push toward filling existing bins harder.
    score += 0.05 * mean_residual;

    // Small deterministic tie-breaker based on residual to stabilize selection.
    score += 0.01 * (post_residual as f64 % 7.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with sharpened non-linear dead-space penalty.
    let mut score = pr;
    let dead = norm_pr.powi(3) * 24.0 + norm_pr.powi(4) * 18.0;
    score -= dead;
    if norm_pr < 0.15 && post_residual > 0 {
        score += (0.15 - norm_pr) * 95.0 * (1.0 - progress);
    }

    // Polynomial progress coupling.
    score += pr * (0.5 + 0.5 * progress * progress) - 0.5 * pr;

    // Relative fit quality vs mean residual.
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 10.0 * (1.0 - progress);

    // Lookahead chaining with two-step window.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fits = (post_residual - next_item_size) as f64;
            score -= fits * 0.3 * (1.0 - progress);
            if fits <= 8.0 {
                score -= 35.0 * (1.0 - fits / 8.0);
            }
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 24.0 * fit_ratio * (1.0 - progress);
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 12 {
                score -= 3.5 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
            }
            if after_next >= item_size {
                score -= 10.0;
            }
            if after_next >= next_item_size {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
            if gap <= 5.0 {
                score += 10.0 * (1.0 - gap / 5.0) * (1.0 - progress);
            }
        }
    } else {
        score -= 35.0 * (1.0 - norm_pr);
    }

    // Tight-fill bonuses with exact-hit escalation.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 22.0 * (fill - 0.75);
    }
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    }

    // Dead-residual band / perfect fill.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 8 {
        score += 60.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // Last-chance preference.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual consolidation.
    let dev = mean_residual - pr;
    score -= 0.22 * dev.clamp(-50.0, 50.0);

    // Open-bin pressure, smooth.
    score += open_bins_count as f64 * (1.2 + 1.8 * progress);
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // Granularity alignment.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Mid-band residual preference early in the stream.
    if norm_pr >= 0.25 && norm_pr <= 0.55 && progress < 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation guard.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Multi-fit competition term.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // Waste-aware residual bucket penalty.
    if post_residual > 0 && progress < 0.9 {
        let dead_zone = if post_residual < 24 { post_residual as f64 / 24.0 } else { 0.0 };
        score += 9.0 * dead_zone * (1.0 - progress);
        if post_residual >= 25 && post_residual <= 60 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Tightness-of-fit variance reduction.
    if post_residual > 0 && mean_residual > 0.0 {
        let spread = ((pr - mean_residual) / mean_residual).abs();
        score += 4.0 * spread.min(2.0) * progress;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && item_size as f64 > 0.85 * cap && progress < 0.4 {
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64 - next_item_size as f64).max(0.0);
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress);
            }
            let fresh_full = (cap - item_size as f64).max(0.0);
            if fresh_full <= existing_res + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
            if fresh_res <= 10.0 && existing_res > 20.0 {
                score -= 20.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        if item_size == bin_capacity {
            score -= 120.0;
        }
        // Fresh-bin gate: open a fresh bin only when its post-fit residual
        // clearly dominates what any existing bin could leave.
        let fresh_after = (cap - item_size as f64).max(0.0);
        let best_existing_after = (mean_residual - item_size as f64).max(0.0);
        if fresh_after > best_existing_after + 8.0 {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
        // Consolidation pressure for small items late in the stream.
        if item_size < 40 && progress > 0.45 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        // Prefer a fresh bin when the item would leave a large stranded
        // residual in every existing bin but fits snugly into a fresh one.
        if fitting_bins_count > 0 && item_size as f64 > 0.7 * cap {
            let snug = (cap - item_size as f64) <= 20.0;
            let stranded = mean_residual > item_size as f64 + 25.0;
            if snug && stranded {
                score -= 16.0 * (1.0 - progress);
            }
        }
        // GEN 25: open a fresh bin when it produces a near-exact two-item
        // completion that no existing bin could replicate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let pair_left = cap - item_size as f64 - next_item_size as f64;
            if pair_left >= 0.0 && pair_left <= 4.0 {
                score -= 20.0 * (1.0 - progress);
            }
            // GEN 27: exact pair completion that no existing bin can chain.
            if pair_left == 0.0 && mean_residual < item_size as f64 + next_item_size as f64 {
                score -= 26.0 * (1.0 - progress);
            }
        }
        // GEN 33: fresh-bin residual-quality gate — open a new bin when its
        // post-fit residual lands in the reusable sweet spot while existing
        // bins would strand unusable slivers.
        if fitting_bins_count > 0 && progress < 0.8 {
            let fresh_after = cap - item_size as f64;
            let stranded_elsewhere = mean_residual - item_size as f64;
            if fresh_after >= 25.0 && fresh_after <= 55.0
                && stranded_elsewhere < 18.0 && stranded_elsewhere >= 0.0 {
                score -= 10.0 * (1.0 - progress);
            }
        }
    }

    // Residual-hoarding penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size + 40 && progress < 0.8 {
        score += 6.0 * (1.0 - progress);
    }

    // Pair-completion bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0 * (1.0 - progress);
    }

    // Near-miss chain sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 4.0 {
            score += 14.0 * (1.0 - miss / 4.0) * (1.0 - progress);
        }
    }

    // Adaptive consolidation — late stream, close bins out aggressively.
    if progress > 0.7 && post_residual > 0 {
        score += pr * 0.25 * (progress - 0.7) / 0.3;
    }

    // Residual symmetry: multiples of 5 are likelier future item sizes.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.0 * (1.0 - progress);
    }

    // Large-item reservation.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress);
    }

    // Dead-space elimination sweep.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // Mid-residual dead-zone tightening.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // Residual-reuse probability shaping.
    if post_residual > 0 && progress < 0.85 {
        let reuse = (post_residual.min(100) as f64) / 100.0;
        score -= 8.0 * reuse * (1.0 - progress);
        if post_residual > 70 {
            score += 10.0 * (1.0 - progress) * ((post_residual as f64 - 70.0) / 30.0).min(1.0);
        }
    }

    // Triple-chain lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // Dead-space ratio shaping — U-curve rewarding residuals in the
    // 30..=60 sweet spot, penalizing stranded slivers and oversized leftovers.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 28.0).min(1.0);
        score -= 9.5 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Two-item lookahead — close bins whose next fill plus mean demand
    // nearly exhausts the bin.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // Waste-rate coupling.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // Near-miss hard penalty — residuals barely too small for the next item
    // are the worst kind of waste.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 4.0 * (1.0 - miss / 10.0) * (1.0 - progress);
        }
    }

    // Late-stream exact-closure.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 12.0 * progress;
    }

    // GEN 29 refinement: residual-similarity tie-break — among comparable
    // fits, prefer the bin whose post-residual most closely matches the
    // running mean residual, reducing residual variance across open bins.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let sim = 1.0 - ((pr - mean_residual) / (mean_residual + 20.0)).abs().min(1.0);
        score -= 6.0 * sim * (1.0 - progress);
    }

    // GEN 29 refinement: bin-closure momentum — when multiple bins are open,
    // reward near-exhausting fits to close bins out.
    if post_residual > 0 && open_bins_count > 1 && item_size as f64 >= 0.85 * bin_residual as f64 {
        score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // GEN 29: stranded-sliver guard — penalize leaving a residual just under
    // a small-item size band when the stream is still mid-flight.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && next_item_size <= 30 && progress < 0.75 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 7.0 * (1.0 - miss / 6.0) * (1.0 - progress);
        }
    }

    // GEN 33: dead-space ratio refinement — sharpen the U-curve around the
    // measured sweet spot and add a graded penalty for oversized leftovers
    // that scales with how far they exceed the reusable band.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 28.0).min(1.0);
        score -= 11.0 * (1.0 - sweet) * (1.0 - sweet) * (1.0 - progress);
        if r > 60.0 {
            let over = (r - 60.0).min(40.0);
            score += 0.12 * over * (1.0 - progress);
        }
    }

    // GEN 33: fill-ratio shaping — reward fits that consume a large fraction
    // of the current residual while leaving a mid-band remainder.
    if post_residual > 0 && bin_residual > item_size {
        let consumed = item_size as f64 / bin_residual.max(1) as f64;
        let remainder_ok = pr >= 20.0 && pr <= 60.0;
        if consumed >= 0.6 && remainder_ok {
            score -= 6.0 * consumed * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;

    // Normalized post residual in [0,1]
    let x = post / cap;

    // Non-linear polynomial in post_residual, modulated by stream progress
    let mut score = post * (1.0 + 0.8 * progress)          // waste penalized more later in stream
        - 0.35 * post * (1.0 - x) * (1.0 + progress)       // reward tight fits (small x), stronger late
        + 0.25 * cap * x * x * (1.0 - progress)            // large dead space penalized more early
        - 0.15 * fit * (1.0 - x * x);                      // reward big items into tight bins

    // Lookahead coupling: if next item fits the post residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 6.0 * (nx / cap) * (1.0 - progress * 0.5);
        } else {
            score += 3.0 * ((nx - post) / cap);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).ln();
    }

    // Mild pressure toward consolidating into existing bins vs. opening new ones
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    let dev = post - mean_residual;
    score += 0.05 * dev * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with sharpened non-linear dead-space penalty.
    let mut score = pr;
    let dead = norm_pr.powi(3) * 24.0 + norm_pr.powi(4) * 18.0;
    score -= dead;
    if norm_pr < 0.15 && post_residual > 0 {
        score += (0.15 - norm_pr) * 95.0 * (1.0 - progress);
    }

    // Polynomial progress coupling.
    score += pr * (0.5 + 0.5 * progress * progress) - 0.5 * pr;

    // Relative fit quality vs mean residual.
    let mr = mean_residual.max(0.0);
    let rel = pr / (mr + 1.0);
    score -= rel * rel * 10.0 * (1.0 - progress);

    // Lookahead chaining with two-step window.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fits = (post_residual - next_item_size) as f64;
            score -= fits * 0.3 * (1.0 - progress);
            if fits <= 8.0 {
                score -= 35.0 * (1.0 - fits / 8.0);
            }
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 24.0 * fit_ratio * (1.0 - progress);
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 12 {
                score -= 3.5 * (1.0 - after_next as f64 / 12.0) * (1.0 - progress);
            }
            if after_next >= item_size {
                score -= 10.0;
            }
            if after_next >= next_item_size {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
            if gap <= 5.0 {
                score += 10.0 * (1.0 - gap / 5.0) * (1.0 - progress);
            }
        }
    } else {
        score -= 35.0 * (1.0 - norm_pr);
    }

    // Tight-fill bonuses with exact-hit escalation.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 35.0 * (fill - 0.9) + 15.0;
    } else if fill > 0.75 {
        score -= 22.0 * (fill - 0.75);
    }
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    if slack >= 0.0 && slack <= 3.0 {
        score -= 45.0 * (1.0 - slack / 3.0);
    }

    // Dead-residual band / perfect fill.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 8 {
        score += 60.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // Last-chance preference.
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Mean-residual consolidation.
    let dev = mean_residual - pr;
    score -= 0.22 * dev.clamp(-50.0, 50.0);

    // Open-bin pressure, smooth.
    score += open_bins_count as f64 * (1.2 + 1.8 * progress);
    score += (open_bins_count as f64).powi(2) * 0.01 * (1.0 - progress);

    // Granularity alignment.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Mid-band residual preference early in the stream.
    if norm_pr >= 0.25 && norm_pr <= 0.55 && progress < 0.5 {
        score -= 6.0 * (1.0 - progress);
    }

    // Fragmentation guard.
    if item_size <= 15 && bin_residual > 60 && fitting_bins_count > 1 && progress < 0.7 {
        score += 10.0 * (1.0 - progress);
    }

    // Multi-fit competition term.
    if fitting_bins_count > 1 && post_residual > 0 {
        let demand = mean_residual.max(1.0);
        let match_q = 1.0 - ((pr - demand) / demand.max(20.0)).abs();
        score -= 8.0 * match_q * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // Endgame sweep.
    if progress > 0.85 {
        score += pr * 0.15;
        if post_residual == 0 {
            score -= 60.0 * (progress - 0.85) / 0.15;
        }
    }

    // Waste-aware residual bucket penalty.
    if post_residual > 0 && progress < 0.9 {
        let dead_zone = if post_residual < 24 { post_residual as f64 / 24.0 } else { 0.0 };
        score += 9.0 * dead_zone * (1.0 - progress);
        if post_residual >= 25 && post_residual <= 60 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Tightness-of-fit variance reduction.
    if post_residual > 0 && mean_residual > 0.0 {
        let spread = ((pr - mean_residual) / mean_residual).abs();
        score += 4.0 * spread.min(2.0) * progress;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let crowding = 1.0 / (1.0 + (mean_residual / cap).exp());
        score += pr * 0.4;
        score -= 25.0 * crowding * (0.5 + progress);
        score -= 15.0 * progress * progress;
        if item_size > 65 && item_size as f64 > 0.85 * cap && progress < 0.4 {
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        if progress > 0.6 {
            score += 25.0;
        }
        if item_size < 30 && mean_residual > 40.0 {
            score += 18.0 * (1.0 - progress);
        }
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if (cap - pair).abs() <= 6.0 {
                score -= 30.0 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let fresh_res = (cap - item_size as f64 - next_item_size as f64).max(0.0);
            let existing_res = (mean_residual - item_size as f64).max(0.0);
            if fresh_res >= existing_res - 4.0 && fresh_res < next_item_size as f64 {
                score -= 12.0 * (1.0 - progress);
            }
            let fresh_full = (cap - item_size as f64).max(0.0);
            if fresh_full <= existing_res + 10.0 {
                score += 14.0 * (1.0 - progress);
            }
            if fresh_res <= 10.0 && existing_res > 20.0 {
                score -= 20.0 * (1.0 - progress);
            }
        }
        if item_size as f64 >= cap * 0.55 {
            score -= 10.0 * (item_size as f64 / cap) * (1.0 - progress);
        }
        if item_size == bin_capacity {
            score -= 120.0;
        }
        // Fresh-bin gate: open a fresh bin only when its post-fit residual
        // clearly dominates what any existing bin could leave.
        let fresh_after = (cap - item_size as f64).max(0.0);
        let best_existing_after = (mean_residual - item_size as f64).max(0.0);
        if fresh_after > best_existing_after + 8.0 {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
        // Consolidation pressure for small items late in the stream.
        if item_size < 40 && progress > 0.45 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        // Prefer a fresh bin when the item would leave a large stranded
        // residual in every existing bin but fits snugly into a fresh one.
        if fitting_bins_count > 0 && item_size as f64 > 0.7 * cap {
            let snug = (cap - item_size as f64) <= 20.0;
            let stranded = mean_residual > item_size as f64 + 25.0;
            if snug && stranded {
                score -= 16.0 * (1.0 - progress);
            }
        }
        // GEN 25: open a fresh bin when it produces a near-exact two-item
        // completion that no existing bin could replicate.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let pair_left = cap - item_size as f64 - next_item_size as f64;
            if pair_left >= 0.0 && pair_left <= 4.0 {
                score -= 20.0 * (1.0 - progress);
            }
            // GEN 27: exact pair completion that no existing bin can chain.
            if pair_left == 0.0 && mean_residual < item_size as f64 + next_item_size as f64 {
                score -= 26.0 * (1.0 - progress);
            }
        }
        // GEN 33: fresh-bin dead-space parity — only open a new bin when its
        // leftover fraction beats the mean existing leftover fraction; else
        // penalize heavily to force consolidation into open bins.
        if fitting_bins_count > 0 {
            let fresh_frac = fresh_after / cap;
            let mean_frac = (mean_residual / cap).max(0.0);
            if fresh_frac > mean_frac + 0.03 {
                score += 30.0 * (fresh_frac - mean_frac) * cap * 0.15;
            } else if fresh_frac < mean_frac - 0.03 {
                score -= 12.0 * (1.0 - progress);
            }
        }
    }

    // Residual-hoarding penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size + 40 && progress < 0.8 {
        score += 6.0 * (1.0 - progress);
    }

    // Pair-completion bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0 * (1.0 - progress);
    }

    // Near-miss chain sharpening.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 4.0 {
            score += 14.0 * (1.0 - miss / 4.0) * (1.0 - progress);
        }
    }

    // Adaptive consolidation — late stream, close bins out aggressively.
    if progress > 0.7 && post_residual > 0 {
        score += pr * 0.25 * (progress - 0.7) / 0.3;
    }

    // Residual symmetry: multiples of 5 are likelier future item sizes.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.0 * (1.0 - progress);
    }

    // Large-item reservation.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress);
    }

    // Dead-space elimination sweep.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // Mid-residual dead-zone tightening.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // Exact-fill lookahead.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // Residual-reuse probability shaping.
    if post_residual > 0 && progress < 0.85 {
        let reuse = (post_residual.min(100) as f64) / 100.0;
        score -= 8.0 * reuse * (1.0 - progress);
        if post_residual > 70 {
            score += 10.0 * (1.0 - progress) * ((post_residual as f64 - 70.0) / 30.0).min(1.0);
        }
    }

    // Triple-chain lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // Dead-space ratio shaping — U-curve rewarding residuals in the
    // 30..=60 sweet spot, penalizing stranded slivers and oversized leftovers.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 28.0).min(1.0);
        score -= 9.5 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Two-item lookahead — close bins whose next fill plus mean demand
    // nearly exhausts the bin.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // Waste-rate coupling.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // Near-miss hard penalty — residuals barely too small for the next item
    // are the worst kind of waste.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 4.0 * (1.0 - miss / 10.0) * (1.0 - progress);
        }
    }

    // Late-stream exact-closure.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 12.0 * progress;
    }

    // GEN 29 refinement: residual-similarity tie-break — among comparable
    // fits, prefer the bin whose post-residual most closely matches the
    // running mean residual, reducing residual variance across open bins.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let sim = 1.0 - ((pr - mean_residual) / (mean_residual + 20.0)).abs().min(1.0);
        score -= 6.0 * sim * (1.0 - progress);
    }

    // GEN 29 refinement: bin-closure momentum — when multiple bins are open,
    // reward near-exhausting fits to close bins out.
    if post_residual > 0 && open_bins_count > 1 && item_size as f64 >= 0.85 * bin_residual as f64 {
        score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // GEN 29: stranded-sliver guard — penalize leaving a residual just under
    // a small-item size band when the stream is still mid-flight.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && next_item_size <= 30 && progress < 0.75 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 7.0 * (1.0 - miss / 6.0) * (1.0 - progress);
        }
    }

    // GEN 33: dead-space ratio refinement — sharpen the U-curve by coupling
    // it to the fill ratio so that bins filled to 0.8–1.0 of their residual
    // are strongly preferred, directly targeting wasted dead space.
    if post_residual > 0 && bin_residual > item_size && progress < 0.9 {
        let used_frac = item_size as f64 / bin_residual.max(1) as f64;
        if used_frac >= 0.8 {
            score -= 14.0 * (used_frac - 0.8) / 0.2 * (1.0 - progress);
        } else if used_frac < 0.5 {
            score += 8.0 * (0.5 - used_frac) / 0.5 * (1.0 - progress);
        }
    }

    // GEN 33: residual-quota shaping — when total remaining demand (mean
    // residual) can be absorbed by this bin's post-residual, reward it so
    // residual space is consumed rather than fragmented across bins.
    if post_residual > 0 && mean_residual > 0.0 && progress < 0.85 {
        let absorb = (pr / mean_residual).min(2.0);
        score -= 5.0 * absorb * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits strongly.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powf(0.5));

    // Harmonic class of post_residual: dead space that is "harmonically useful"
    // (small or matching common item sizes) is less harmful.
    let dead = post_residual as f64;
    if dead > 0.0 {
        // Class A: post_residual divisible by common item blocks (10/20/25) -> reusable
        let reusable = (post_residual % 10 == 0) || (post_residual % 25 == 0);
        if reusable {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Class B: tiny unusable slivers (post_residual < 10) are pure waste
        if post_residual < 10 {
            score += 12.0;
        }
        // Integer-division threshold: post_residual / item_size class
        let div_class = post_residual / item_size.max(1);
        if div_class == 0 {
            score += 3.0; // item dominates remaining space, leftover awkward
        } else if div_class >= 2 {
            score -= 2.0; // space can host multiple future mid-size items
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (post_residual as f64 - next_item_size as f64).min(10.0) / 10.0;
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 3.0;
        }
        // Harmonic pairing: next_item + item exactly fills capacity
        if item_size + next_item_size == bin_capacity && bin_residual == bin_capacity {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Late in stream or many open bins with large mean residual -> prefer reuse
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 20.0 * pressure + 6.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild preference for consolidating into bins below mean residual (balance).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

