    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // Near-miss hard penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 4.0 * (1.0 - miss / 10.0) * (1.0 - progress);
        }
    }

    // Late-stream exact-closure.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 12.0 * progress;
    }

    // GEN 35: residual-similarity tie-break — prefer post-residuals matching
    // the running mean residual to homogenize open-bin slack.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let sim = 1.0 - ((pr - mean_residual) / (mean_residual + 20.0)).abs().min(1.0);
        score -= 6.0 * sim * (1.0 - progress);
    }

    // GEN 35: bin-closure momentum — reward near-exhausting fits when
    // multiple bins compete.
    if post_residual > 0 && open_bins_count > 1 && item_size as f64 >= 0.85 * bin_residual as f64 {
        score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // GEN 35: stranded-sliver guard — penalize residuals just under a
    // small-item size band mid-stream.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && next_item_size <= 30 && progress < 0.75 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 7.0 * (1.0 - miss / 6.0) * (1.0 - progress);
        }
    }

    // GEN 35: dead-space variance coupling — when residual variance pressure
    // is high, sharpen the preference for exact/near-exhausting placements.
    if post_residual > 0 && progress > 0.35 && fitting_bins_count > 1 {
        let tight = 1.0 - (pr / cap).min(1.0);
        score -= 5.0 * tight * (progress - 0.35).min(0.4);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Strict dead-space avoidance: tiny unusable gaps are heavily penalized
        score += 20.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Moderate gap: mildly penalized, still usable
        score += 3.0;
    }

    // New-bin candidate: discourage opening a bin when open bins can fit,
    // unless the fit elsewhere is terrible (handled by dead-space penalties)
    if bin_residual == bin_capacity {
        score += 10.0 + 0.4 * open_bins_count as f64;
    }

    // Open-bins pressure: mild consolidation pressure scaled by stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: reward bins that can also host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0;
        } else if post_residual > 0 {
            score += 2.0;
        }
    }

    // Prefer bins tighter than the average residual (best-fit flavor)
    score += 0.05 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

