    // GEN 29: stranded-sliver guard — penalize leaving a residual just under
    // a small-item size band when the stream is still mid-flight.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && next_item_size <= 30 && progress < 0.75 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 7.0 * (1.0 - miss / 6.0) * (1.0 - progress);
        }
    }

    // GEN 35: residual-variance compaction — with several open bins, reward
    // post-residuals that sit near the open-bin residual mean so future small
    // items can combine across bins; sharpen slightly with fit competition.
    if post_residual > 0 && open_bins_count > 2 && fitting_bins_count > 1 && progress < 0.85 {
        let align = 1.0 - ((pr - mean_residual) / 30.0).abs().min(1.0);
        score -= 5.0 * align * (1.0 - progress);
    }

    // GEN 35: dead-space ratio refinement — retune the U-curve center toward
    // the empirically denser band and add a graded penalty for residuals in
    // the awkward 15..=25 gap band that rarely hosts upcoming items.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 42.0).abs() / 30.0).min(1.0);
        score -= 3.0 * (1.0 - sweet) * (1.0 - progress);
        if r >= 15.0 && r <= 25.0 {
            score += 6.0 * (1.0 - progress) * (1.0 - ((r - 20.0).abs() / 5.0));
        }
    }

    // GEN 35: near-perfect fill escalation — deepen the reward for fits
    // leaving under 5 units, with a mild progress tilt to close bins early.
    if post_residual > 0 && post_residual <= 5 {
        score -= 10.0 * (1.0 - post_residual as f64 / 5.0) * (0.6 + 0.4 * progress);
    }

    // GEN 35: next-item exact pair into residual — strong bonus when the
    // next item exactly consumes the residual, scaled by open-bin pressure.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 4.0 * (open_bins_count as f64).min(6.0) * (1.0 - progress);
    }

    score
}

