    // 30..=60 sweet spot, penalizing stranded slivers and oversized leftovers.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 28.0).min(1.0);
        score -= 9.5 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Two-item lookahead — close bins whose next fill plus mean demand
    // nearly exhausts the bin.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // Waste-rate coupling.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // Near-miss hard penalty — residuals barely too small for the next item
    // are the worst kind of waste.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 10.0 {
            score += 4.0 * (1.0 - miss / 10.0) * (1.0 - progress);
        }
    }

    // Late-stream exact-closure.
    if next_item_size > 0 && next_item_size == post_residual && progress > 0.5 {
        score -= 12.0 * progress;
    }

    // GEN 29 refinement: residual-similarity tie-break — among comparable
    // fits, prefer the bin whose post-residual most closely matches the
    // running mean residual, reducing residual variance across open bins.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let sim = 1.0 - ((pr - mean_residual) / (mean_residual + 20.0)).abs().min(1.0);
        score -= 6.0 * sim * (1.0 - progress);
    }

    // GEN 29 refinement: bin-closure momentum — when multiple bins are open,
    // reward near-exhausting fits to close bins out.
    if post_residual > 0 && open_bins_count > 1 && item_size as f64 >= 0.85 * bin_residual as f64 {
        score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // GEN 29: stranded-sliver guard — penalize leaving a residual just under
    // a small-item size band when the stream is still mid-flight.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && next_item_size <= 30 && progress < 0.75 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 6.0 {
            score += 7.0 * (1.0 - miss / 6.0) * (1.0 - progress);
        }
    }

    // GEN 36 refinement: residual-similarity tie-break strengthened and
    // extended to all multi-fit situations with a smoother kernel.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let sim = 1.0 - ((pr - mean_residual) / (mean_residual + 25.0)).abs().min(1.0);
        score -= 3.5 * sim * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // GEN 36 refinement: adaptive U-curve center — track the mean residual
    // scale so the sweet spot follows the actual stream distribution instead
    // of a fixed 45-unit band.
    if post_residual > 0 && progress < 0.9 && mean_residual > 8.0 {
        let center = mean_residual.clamp(20.0, 60.0);
        let adapt = ((pr - center).abs() / (center + 15.0)).min(1.0);
        score -= 5.0 * (1.0 - adapt) * (1.0 - progress);
    }

    // GEN 36 refinement: near-exhaustion bonus scaled by bin crowding —
    // with many open bins, closing one out is worth more.
    if post_residual > 0 && post_residual <= 15 && open_bins_count > 2 {
        score -= 8.0 * (1.0 - post_residual as f64 / 15.0) * (open_bins_count as f64).min(8.0) / 8.0;
    }

    // GEN 36 refinement: fresh-bin gate tightened — when an existing bin
    // leaves a residual within the next item's reach, strongly prefer it.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let fresh_res = (cap - item_size as f64).max(0.0);
        if fresh_res < next_item_size as f64 && mean_residual >= next_item_size as f64 {
            score += 24.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit: dead space eliminated.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the leftover space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Penalize if the leftover space cannot fit the next item (dead space risk),
    // scaled by how much wasted potential there is.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.8 * (next_item_size - post_residual) as f64;
    }
    // Reward if the leftover can fit the next item with room to spare.
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 0.3 * (post_residual - next_item_size) as f64;
    }

    // Last-chance bonus: this is the only bin that fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to the bin or current bins are very full.
    if bin_residual == bin_capacity {
        score += 60.0;
        if item_size >= 70 {
            score -= 40.0; // big items: fresh bin is fine
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress; // late in stream, prefer consolidating into open bins
    }

    // Prefer tighter bins relative to the mean residual (best-fit flavor).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Mild penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

