    // Exact-fill lookahead.
    if next_item_size > 0 && post_residual > 0 {
        let near = (post_residual as i64 - next_item_size as i64).abs();
        if near <= 2 {
            score -= 18.0 * (1.0 - near as f64 / 2.0) * (1.0 - progress);
        }
    }

    // Residual-reuse probability shaping.
    if post_residual > 0 && progress < 0.85 {
        let reuse = (post_residual.min(100) as f64) / 100.0;
        score -= 8.0 * reuse * (1.0 - progress);
        if post_residual > 70 {
            score += 10.0 * (1.0 - progress) * ((post_residual as f64 - 70.0) / 30.0).min(1.0);
        }
    }

    // Triple-chain lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // GEN 39: residual-similarity tie-break — prefer residuals matching the
    // running mean demand so future items can still be consolidated.
    if post_residual > 0 && mean_residual > 0.0 && fitting_bins_count > 1 {
        let sim = 1.0 - ((pr - mean_residual) / (mean_residual + 20.0)).abs().min(1.0);
        score -= 6.0 * sim * (1.0 - progress);
    }

    // GEN 39: bin-closure momentum — strongly reward near-exhausting fits.
    if post_residual > 0 && open_bins_count > 1 && item_size as f64 >= 0.85 * bin_residual as f64 {
        score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // GEN 39: dead-space ratio U-curve.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 28.0).min(1.0);
        score -= 10.5 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Two-item lookahead: next item + mean demand nearly exhausts the bin.
    if next_item_size > 0 && post_residual > 0 {
        let chain = next_item_size as f64 + mean_residual.max(0.0);
        if chain >= pr && chain - pr <= 12.0 {
            score -= 11.0 * (1.0 - (chain - pr) / 12.0) * (1.0 - progress);
        }
    }

    // Waste-rate coupling.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // GEN 39 mutation A: combined fine-grain fit + lookahead coupling —
    // when the current fill is near-perfect AND the next item exactly
    // matches the post-residual, escalate the closure reward.
    if post_residual > 0 && next_item_size > 0 && next_item_size == post_residual && fill > 0.8 {
        score -= 14.0 * (1.0 - progress) * fill;
    }

    // GEN 39 mutation B: dead-space ratio target — penalize residuals that
    // fall in the "stranded sliver" band (just below typical item sizes)
    // more sharply when many bins are open (waste compounds).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size
        && next_item_size - post_residual <= 15 && open_bins_count > 2 {
        score += 6.0 * (1.0 - (next_item_size - post_residual) as f64 / 15.0) * (1.0 - progress);
    }

    // GEN 39 mutation C: consolidation of medium residuals into fewer bins —
    // when fitting_bins_count is small and the residual stays workable,
    // reward keeping the item out of a fresh bin.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && post_residual >= 20 && progress < 0.6 {
        score += 9.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
