        score -= 7.0 * (1.0 - band) * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

    // GEN 38 mutation: slack-harmonic bonus — reward fits leaving a residual
    // close to a small divisor of the capacity (likely reusable chunk).
    if post_residual > 0 && progress < 0.75 {
        let r = post_residual as f64;
        if (r - 25.0).abs() <= 3.0 || (r - 50.0).abs() <= 3.0 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // GEN 38 mutation: fresh-bin dominance tightening — require a bigger
    // margin before opening a new bin late in the stream.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && progress > 0.5 {
        let fresh_after = (cap - item_size as f64).max(0.0);
        let best_existing_after = (mean_residual - item_size as f64).max(0.0);
        if fresh_after <= best_existing_after + 3.0 {
            score += 12.0 * (progress - 0.5) / 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with sharpened dead-space penalty.
    let mut score = pr;
    let dead = norm_pr.powi(3) * 24.0 + norm_pr.powi(4) * 18.0;
    score -= dead;
    if norm_pr < 0.15 && post_residual > 0 {
        score += (0.15 - norm_pr) * 95.0 * (1.0 - progress);
    }

    // Progress coupling: early tight packing, later tolerance.
    score += pr * (0.5 + 0.5 * progress * progress) - 0.5 * pr;

    // Relative fit quality vs mean residual.
    let mr = mean_residual.max(0.0);
