    // minimum toward 45 and extend its reach, since residual variance is
    // already low; tightening the sweet spot squeezes out the last bins.
    if post_residual > 0 && progress < 0.92 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 24.0).min(1.0);
        score -= 11.5 * (1.0 - sweet) * (1.0 - progress);
        if r < 8 && r < next_item_size as f64 {
            score += 6.0 * (1.0 - progress);
        }
    }

