    // residual after this item can host the next item AND still leave
    // a small reusable tail; penalize one-shot fits that strand the bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = (post_residual - next_item_size) as f64;
        if after >= 5.0 && after <= 25.0 {
            score -= 7.0 * (1.0 - progress) * (1.0 - ((after - 5.0) / 20.0).abs());
        }
        if after > 45.0 && mean_residual < 30.0 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // GEN 39 mutation: slack-quantization penalty — post-residuals just
    // below common item-size boundaries (e.g. 11..14, 21..24, 31..34)
    // are hard to refill; nudge selection toward cleaner boundaries.
    if post_residual > 0 && progress < 0.85 {
        let r = post_residual;
        let band = (r % 10);
        if band >= 1 && band <= 4 && r > 10 {
            score += 3.0 * (1.0 - progress);
        } else if band >= 5 && band <= 9 && r > 15 {
            score -= 2.5 * (1.0 - progress);
        }
    }

    score
}

