    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // GEN 39 mutation: large-item reservation — protect space for big next items.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress);
    }

    // GEN 39 mutation: dead-space elimination sweep for tiny residuals.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // GEN 39 mutation: mid-residual dead-zone tightening around 40, widened
    // to 28..=52 with a sharper center for better recombination targeting.
    if post_residual >= 28 && post_residual <= 52 && progress < 0.65 {
        score += 8.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 12.0));
    }

    // GEN 39 mutation: tightness-of-fit variance reduction, slightly stronger.
    if post_residual > 0 && mean_residual > 0.0 {
        let spread = ((pr - mean_residual) / mean_residual).abs();
        score += 5.0 * spread.min(2.0) * progress;
    }

    score
}

