    // the next item size is dead space; steer away from it smoothly.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 20.0 {
            score += 3.0 * (1.0 - miss / 20.0) * (1.0 - progress);
        }
    }

    // GEN 40 mutation: consolidation sweep — mid-stream, mildly favor
    // leaving residuals near the mean demand so future items keep fitting.
    if post_residual > 0 && progress > 0.3 && progress < 0.85 && mean_residual > 0.0 {
        let dev2 = ((pr - mean_residual) / (mean_residual + 10.0)).abs();
        score += 2.5 * dev2.min(1.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are penalized hard.
    // A gap that no future item (min size 1) can ever fill usefully is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Medium-small gaps: moderate penalty, they may fit small items.
        score += 15.0;
    }

    // Prefer bins whose residual tightly matches the item (low relative slack).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base new-bin cost: opening a bin is expensive.
        score += 40.0;
        // If many bins can fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 80.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If the current bin would leave a tiny dead gap, a fresh bin looks better.
        if post_residual > 0 && post_residual < 10 {
            score -= 55.0;
        }
        // Lookahead: if next item is large, a fresh bin with room is valuable.
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 30.0;
        }
        // Pressure: many open bins already -> discourage opening yet another.
        score += open_bins_count as f64 * 4.0;
    } else {
        // Existing bin: mild reward when open bins are few (consolidate early).
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Lookahead synergy: reward placing item so residual fits the next item exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_slack = (post_residual - next_item_size) as f64;
        if next_slack < 10.0 {
            score -= 25.0; // chain fit: this placement sets up an exact-ish next fit
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for next item: penalize slightly (dead space for lookahead).
        score += 10.0;
    }

    // Stream progression: late in the stream, prefer tighter packing (less room to fix mistakes).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64).abs() * 0.5;

    score
}

