    // common item size threshold waste the most; sharpen the near-miss band
    // for medium residuals (15..=35) relative to next-item demand.
    if post_residual > 0 && next_item_size > post_residual && post_residual >= 15 && post_residual <= 35 {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 15.0 {
            score += 6.0 * (1.0 - miss / 15.0) * (1.0 - progress);
        }
    }

