    let remaining = total_items.saturating_sub(step_index).max(1) as f64;
    if open_bins_count as f64 > remaining * 0.6 && post_residual > 0 {
        score += pr * 0.12;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    if next_item_size > 0 {
        // Perfect 2-step match: post_residual exactly fits the next item.
        if post_residual == next_item_size {
            score -= 100.0;
        }
        // Next item fits exactly into current residual (1-step perfect match).
        if bin_residual == item_size + next_item_size {
            score -= 60.0;
        }
        // Next item fits into the post-residual space: reward proportionally.
        if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to the next item: penalize unusable gap.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.8;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 20.0;
    }

    // Relative to mean residual: bins tighter than average are more valuable.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: penalize unless the fit is genuinely poor
    // (opening a new bin only wins when this placement would waste a lot).
    if bin_residual == bin_capacity {
        score += 45.0;
        // But a fresh bin is great for a perfect 2-step chain.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Late in the stream: consolidate harder, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

