    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // GEN 41: small-item consolidation sweep — when the next item is small
    // and would exactly consume the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual && fitting_bins_count > 1 {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class residuals into coarse buckets via integer division on capacity fractions.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Perfect-fit bonus: post_residual near a small harmonic of capacity.
    if post_residual == 0 {
        score -= 1000.0; // exact fit is ideal
    } else if post_residual <= eighth {
        score -= 20.0; // tiny dead space, acceptable
    } else if post_residual <= quarter {
        score -= 5.0; // moderate leftover
    } else {
        score += 10.0; // large leftover: wasteful unless more items coming
    }

    // Modulo-arithmetic coupling: residual classes divisible by common item sizes
    // (10..80 items historically) are more likely to be filled by future items.
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        for m in [10u32, 20, 25, 40, 50, 100] {
            if r % m == 0 && r > 0 {
                b += 4.0;
            }
        }
        b
    };
    score -= harmonic_bonus(post_residual);

    // Lookahead: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
            // penalize leaving awkward gap that barely fails next item
            if post_residual - next_item_size < eighth && post_residual - next_item_size > 0 {
                score += 5.0;
            }
        } else {
            // next item won't fit here; leftover becomes dead space risk
            score += (post_residual as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity and open bins are already fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / cap).clamp(0.0, 1.0)
        } else {
            0.0
        };
        // base cost of a fresh bin
        score += 40.0;
        // worth opening when item is big and existing bins are full-ish
        score -= (item_size as f64 / cap) * 30.0;
        score -= fragmentation * 25.0;
        // early in stream: cheaper to open bins (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    }

    // Mild tie-breaking toward tighter bins overall.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity.max(1) as f64;
