    // it proportionally to how many alternatives exist.
    if post_residual > 0 && fitting_bins_count > 1 && mean_residual > 0.0 {
        let tightness = 1.0 - (pr / (mean_residual + 1.0)).min(1.0);
        score -= 10.0 * tightness * (1.0 - progress) * (1.0 - 1.0 / fitting_bins_count as f64);
    }

