    // the leftover after it equals a small residual (<=15), the bin is
    // effectively closed; escalate the reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if after > 0 && after <= 15 {
            score -= 14.0 * (1.0 - after as f64 / 15.0) * (0.5 + 0.5 * (1.0 - progress));
