    if bin_residual == bin_capacity && item_size as f64 > 0.6 * cap && progress > 0.3 && progress < 0.75 {
        score -= 9.0 * (1.0 - ((progress - 0.3) / 0.45 - 0.5).abs() * 2.0).max(0.0);
    }

    score
}

