    }

    // GEN 42: tightness-of-fit variance reduction.
    if post_residual > 0 && mean_residual > 0.0 {
        let spread = ((pr - mean_residual) / mean_residual).abs();
        score += 4.0 * spread.min(2.0) * progress;
    }

    // GEN 42 NEW: near-exact pair completion — when the fresh-bin residual
    // after placing this item equals the next item exactly, escalate.
    if bin_residual == bin_capacity && next_item_size > 0 {
        let fresh_left = cap - item_size as f64;
        if (fresh_left - next_item_size as f64).abs() <= 1.0 {
            score -= 24.0 * (1.0 - progress);
        }
    }

    // GEN 42 NEW: three-way dominance — if an existing bin would close
    // perfectly (post_residual == 0) and fresh-bin leaves waste, hard
    // penalize fresh to avoid bin inflation.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && item_size as f64 >= 0.8 * cap {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0;
    }

    // Reward tight fits (post_residual near zero but exact fill is best).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Prefer bins whose residual was already small (best-fit character).
    score += 0.15 * (bin_residual as f64);

    // Open-bin pressure: with many open bins, discourage spreading; favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    score += 0.05 * pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more when many bins are open or lookahead fits.
        score += 60.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.2 * (next_item_size as f64);
        }
        score -= 0.1 * mean_residual;
    }

    // Lookahead coupling: penalize leaving a residual that neither fits the next item well
    // nor is zero — encourage post_residual == next_item_size exact sequences.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 10.0;
        }
    }

    score
}

