        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // GEN 42 mutation: granularity alignment — residuals that are multiples
    // of common item sizes are likelier to be reused later.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.0 * (1.0 - progress);
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // GEN 42 mutation: large-item reservation — protect space for big next items.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress);
    }

    // GEN 42 mutation: dead-space elimination sweep for tiny residuals.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // GEN 42 mutation: mid-residual dead-zone tightening around 40.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // GEN 42 mutation: tightness-of-fit variance reduction.
    if post_residual > 0 && mean_residual > 0.0 {
        let spread = ((pr - mean_residual) / mean_residual).abs();
        score += 4.0 * spread.min(2.0) * progress;
    }

    // GEN 42 mutation: next-fit dominance — if the next item exactly fills
    // the post-residual while no other bin could chain as well, lock it in.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count > 1 {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
