    }

    // GEN 45 mutation: mid-residual dead-zone tightening around 40 —
    // narrow the band and scale by stream position for early focus.
    if post_residual >= 32 && post_residual <= 48 && progress < 0.6 {
        score += 9.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 8.0));
    }

    // GEN 45 mutation: tightness-of-fit variance reduction — strengthen
    // the pull toward homogenized residuals mid-stream.
    if post_residual > 0 && mean_residual > 0.0 {
        let spread = ((pr - mean_residual) / mean_residual).abs();
        score += 5.0 * spread.min(2.0) * progress;
    }

