    // space that exceeds the next item's need by a wide margin.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size + 40 && progress < 0.8 {
        let excess = (post_residual - next_item_size - 40) as f64;
        score += 6.0 * (1.0 - progress) + 0.05 * excess;
    }

    // GEN 45 mutation: consolidation sweep — extend the late-stream bin
    // closing pressure with a smooth ramp tied to open-bin count.
    if progress > 0.7 && post_residual > 0 {
        let ramp = (progress - 0.7) / 0.3;
        score += pr * 0.25 * ramp;
        score += (open_bins_count as f64).sqrt() * 2.0 * ramp;
    }

    // GEN 45 mutation: near-miss escalation — deepen the penalty for
    // residuals that just barely fail to host the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 12.0 {
            score += 5.0 * (1.0 - miss / 12.0) * (1.0 - progress);
        }
        if miss <= 5.0 {
            score += 16.0 * (1.0 - miss / 5.0) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins grouped by capacity fraction.
    let q = (post_residual * 4) / bin_capacity; // 0..3 quartile class
    match q {
        0 => score -= 6.0,   // near-perfect fit: strongly reward
        1 => score += 2.0,   // small dead space: mild penalty
        2 => score -= 1.5,   // half-full leftovers stay usable
        _ => score -= 3.0,   // large residual: very reusable
    }

    // Fine harmonic bonus: post_residual divisible by common item sizes (10, 20, 25, 50)
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 2.0; }
        if post_residual % 20 == 0 { score -= 1.0; }
        if post_residual % 25 == 0 { score -= 1.0; }
        if post_residual % 50 == 0 { score -= 1.5; }
    } else {
        score -= 12.0; // exact fill is the best outcome
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
            // integer-division harmony between leftover class and next item
            if (post_residual / next_item_size.max(1)) >= 2 { score -= 1.5; }
        } else {
            score += 3.0; // creates stranded space relative to lookahead
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.35 {
            score -= 5.0 * (0.35 - pressure);
        } else {
            score += 6.0 + 4.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));
        }
    }

    // Progress: early on prefer tight packing, late prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Penalize bins deviating from mean residual (keeps residual distribution balanced)
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

