    if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        let after = (post_residual - next_item_size) as f64;
        if after >= mean_residual.max(0.0) {
            score -= 7.0 * (1.0 - progress);
        } else if after > 0.0 && mean_residual > after {
            score += 6.0 * (1.0 - after / mean_residual.max(1.0)) * (1.0 - progress);
        }
    }

    // GEN 45 mutation: smooth dead-space parabola — penalize residuals far
    // from the reusable ~50 band proportionally, replacing hard bands.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let shape = (r / 50.0 - 1.0).powi(2);
        score += 5.0 * shape * (1.0 - progress) * (1.0 + progress);
    }

    // GEN 45 mutation: best-fit competition sharpening — with several fitting
    // bins, prefer the one leaving residual closest to the mean demand.
    if fitting_bins_count > 1 && post_residual > 0 {
        let target = mean_residual.max(12.0);
        let dist = ((pr - target) / 30.0).abs().min(1.0);
        score += 10.0 * dist * (1.0 - progress);
    }

    // GEN 45 mutation: near-closure regret shaping — bins almost emptied but
    // not exactly are penalized proportionally to how close they came.
    if post_residual > 0 && post_residual <= 5 && progress < 0.95 {
        score += 22.0 * (1.0 - post_residual as f64 / 5.0);
    }

    score
}

