        // Fresh-bin gate: open fresh only when its post-fit residual
        // clearly dominates what any existing bin could leave.
        let fresh_after = (cap - item_size as f64).max(0.0);
        let best_existing_after = (mean_residual - item_size as f64).max(0.0);
        if fresh_after > best_existing_after + 8.0 {
            score -= 14.0 * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
        // Consolidation pressure for small items late in the stream.
        if item_size < 40 && progress > 0.45 && fitting_bins_count > 0 {
            score += 22.0 * progress;
        }
        // Prefer fresh bin when existing bins would strand large residuals
        // but the item fits snugly fresh.
        if fitting_bins_count > 0 && item_size as f64 > 0.7 * cap {
            let snug = (cap - item_size as f64) <= 20.0;
            let stranded = mean_residual > item_size as f64 + 25.0;
            if snug && stranded {
                score -= 16.0 * (1.0 - progress);
            }
        }
    }

    // Residual-hoarding penalty.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size + 40 && progress < 0.8 {
        score += 6.0 * (1.0 - progress);
    }

    // Adaptive consolidation — late stream, close bins out.
    if progress > 0.7 && post_residual > 0 {
        score += pr * 0.25 * (progress - 0.7) / 0.3;
    }

    // Waste-rate coupling.
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 0 {
        score += pr * 0.06;
    }

    // Triple-chain lookahead: post-residual after next item matches mean demand.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        if (after as f64 - mean_residual).abs() <= 5.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // GEN 36 mutation: dead-space ratio U-curve — reward residuals in the
    // 30..=60 sweet spot, penalize stranded slivers and oversized leftovers.
    if post_residual > 0 && progress < 0.9 {
        let r = post_residual as f64;
        let sweet = ((r - 45.0).abs() / 28.0).min(1.0);
        score -= 9.5 * (1.0 - sweet) * (1.0 - progress);
        if r < 10 && r < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // GEN 36 mutation: granularity alignment — residuals that are multiples
    // of common item sizes are likelier to be reused later.
    if post_residual > 0 && post_residual % 5 == 0 && progress < 0.8 {
        score -= 4.0 * (1.0 - progress);
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // GEN 36 mutation: large-item reservation — protect space for big next items.
    if next_item_size > 60 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - progress);
    }

    // GEN 36 mutation: dead-space elimination sweep for tiny residuals.
    if post_residual > 0 && post_residual <= 12 && bin_residual > item_size {
        score += 16.0 * (1.0 - post_residual as f64 / 12.0) * (1.0 - progress);
    }

    // GEN 36 mutation: mid-residual dead-zone tightening around 40.
    if post_residual >= 30 && post_residual <= 50 && progress < 0.65 {
        score += 7.0 * (1.0 - progress) * (1.0 - ((post_residual as f64 - 40.0).abs() / 10.0));
    }

    // GEN 36 mutation: tightness-of-fit variance reduction.
    if post_residual > 0 && mean_residual > 0.0 {
        let spread = ((pr - mean_residual) / mean_residual).abs();
        score += 4.0 * spread.min(2.0) * progress;
    }

    // GEN 46 mutation: two-step chain exhaustion — prefer residuals that the
    // next item plus a plausible follower (mean demand) nearly fill exactly.
    if next_item_size > 0 && post_residual > 0 && progress < 0.85 {
        let chain2 = next_item_size as f64 + mean_residual.max(0.0);
        if chain2 <= pr {
            let leftover = pr - chain2;
            if leftover <= 6.0 {
                score -= 10.0 * (1.0 - leftover / 6.0) * (1.0 - progress);
            }
        }
    }

    // GEN 46 mutation: residual-spectrum shaping — penalize residuals that
    // no plausible item (1..=100) can pair with to near-exhaustion, i.e.
    // residuals just above the next item's size leave unusable slivers.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let sliver = post_residual - next_item_size;
        if sliver > 0 && sliver < 8 && next_item_size > 20 {
            score += 7.0 * (1.0 - sliver as f64 / 8.0) * (1.0 - progress);
        }
    }

    // GEN 46 mutation: endgame exact-closure escalation — in the final stretch
    // any residual that cannot host the next item is pure waste.
    if progress > 0.8 && post_residual > 0 && next_item_size > post_residual {
        score += 12.0 * (progress - 0.8) / 0.2;
    }

    // GEN 46 mutation: fresh-bin residual quality — open a new bin only if
    // its post-fit residual sits in the reusable band relative to the mean
    // demand, otherwise steer the item into an existing partial fit.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let fresh_after = (cap - item_size as f64).max(0.0);
        let band = ((fresh_after - mean_residual.max(1.0)) / 30.0).abs().min(1.0);
        score += 8.0 * band * (0.4 + 0.6 * progress);
        // Large items early are worth a fresh bin even at moderate residual cost.
        if item_size > 50 && progress < 0.35 && fresh_after < 35.0 {
            score -= 9.0 * (1.0 - progress);
        }
    }

    // GEN 46 mutation: mean-residual drift tracking — when the running mean
    // residual is shrinking (stream tightening), favor exact closures more.
    if post_residual > 0 && mean_residual > 0.0 && mean_residual < 20.0 {
        score += pr * 0.05 * (1.0 - mean_residual / 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: strongly favor small post_residual relative to capacity.
    score -= (1.0 - post / cap) * 30.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving dead space that the typical (or lookahead) item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            // dead space for the next item
            score += (nxt - post) * 0.8;
        } else {
            // reward leaving space that fits the lookahead item
            score -= (1.0 - (post - nxt) / cap) * 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Spread load when many bins fit: mild penalty for over-crowding the tightest bin.
        score += (fitting_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Global balance: prefer bins whose residual is near the mean (avoid fragmentation).
    let res = bin_residual as f64;
    score += ((res - mean_residual).abs() / cap) * 6.0;

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, accept tighter fits aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * (40.0 - post.min(40.0));

    // Many open bins: encourage consolidation into existing bins rather than opening new ones.
    score += (open_bins_count as f64) * 0.05;

    // New-bin candidate: penalize opening a new bin unless existing options are poor.
    if bin_residual == bin_capacity {
        score += 55.0 + post * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
